/// The compact policy removes the settled preview, and that must never become
/// an expanded body: the reader's own setting may not turn every reasoning
/// block into full-width prose. Collapsed with the one-line summary is the
/// whole behaviour, and the click is the only way in.
#[gpui::test]
fn the_compact_policy_cannot_expand_a_settled_think_block(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (_harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("think-compact", 1);
        state.settings.global.general.transcript_view = "compact".to_string();
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].reasoning = "first line of thought\n\nmore **detail**".to_string();
            session.messages[1].text = "the answer".to_string();
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let shell = cx.update(|_, cx| _harness.read(cx).shell.clone());
    let policy = cx.update(|_, cx| shell.read(cx).state.effective().transcript_view);
    assert!(
        !policy.settled_reasoning_preview,
        "the premise: this session runs the compact policy"
    );
    assert!(
        cx.debug_bounds("think-summary-1").is_some(),
        "the collapsed row still carries its one-line summary"
    );
    assert!(
        cx.debug_bounds("think-body-1").is_none(),
        "and the body is closed: the setting hides the PREVIEW, never opens the block"
    );

    let hits = cx.debug_bounds("think-row-1").expect("the row bounds");
    cx.simulate_click(hits.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert!(
        cx.debug_bounds("think-body-1").is_some(),
        "the click is the one way in"
    );
}
/// The transcript chrome, from the reference's own `TurnNavigator.module.css` and
/// `MessageItem.module.css`: a 28px rail parked 12px off the transcript's right edge,
/// capped at 420 tall and scrolled when the marks overflow, where a mark is a 10px slot
/// holding a 2px bar drawn at 60% while idle and 100% for the turn at the top; and a
/// user bubble on radius-xl 20 over `10px 16px` with the measured 22px conversation line.
#[gpui::test]
fn the_transcript_takes_the_measured_chrome(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (_harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("transcript-chrome", 60);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            // One short turn pins the measured bubble box exactly.
            session.messages[0] = ChatMessage::user("hi".to_string());
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let transcript = cx.debug_bounds("transcript").expect("the scroller renders");
    let track = cx
        .debug_bounds("turn-rail-track")
        .expect("the rail track renders");

    // The rail rests at its bottom (the newest mark is in view), so the idle
    // mark asserted here is the one just above it; the frame only BUILDS the
    // marks in its 420px window.
    let idle = cx
        .debug_bounds("turn-tick-58")
        .expect("an idle tick renders");
    let bar = cx.debug_bounds("turn-bar-58").expect("its bar renders");
    let last_tick = cx
        .debug_bounds("turn-tick-59")
        .expect("the last tick renders");
    let last_bar = cx.debug_bounds("turn-bar-59").expect("its bar renders");

    assert_eq!(
        track.size.height,
        px(420.0),
        "the measured rail is capped at min(band - 64, 420)"
    );
    assert_eq!(idle.size.width, px(28.0), "a mark spans the 28px frame");
    assert_eq!(idle.size.height, px(10.0), "a mark slot is 10 tall");
    assert_eq!(
        last_tick.size.height,
        px(10.0),
        "every mark slot is 10 tall"
    );
    assert_eq!(
        idle.origin.x + idle.size.width,
        transcript.origin.x + transcript.size.width - px(12.0),
        "the frame sits 12px off the transcript's right edge"
    );
    // Whichever turn's top sits at the viewport's top edge is the active one, so
    // count the marks at scaleX(1) rather than naming the turn: the rail draws one
    // bar at 20px and every other at 12px (60% of the measured 20px bar).
    assert_eq!(bar.size.width, px(12.0), "an idle mark is scaleX(.6)");
    let mut full = 0;
    for turn in 0..60 {
        // `debug_bounds` wants a borrowed selector, so leak the label like the
        // tick-click test does; a test never cares about 60 short strings.
        let selector: &str = Box::leak(format!("turn-bar-{turn}").into_boxed_str());
        if cx
            .debug_bounds(selector)
            .is_some_and(|bounds| bounds.size.width == px(20.0))
        {
            full += 1;
        }
    }
    assert_eq!(full, 1, "exactly one mark is drawn at scaleX(1)");
    assert_eq!(last_tick.size.height, px(10.0));
    assert_eq!(
        last_bar.size.width,
        px(20.0),
        "and the newest mark is the live one at the tail"
    );
    // The first turn is far above the tail, so the WINDOWED transcript keeps it
    // as a spacer until it is scrolled to. Scroll there and read the bubble.
    let shell = cx.update(|_, cx| _harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |shell, _| {
            shell.following_tail = false;
            shell.transcript_scroll.scroll_to_top_of_item(0);
        });
    });
    draw_until(
        cx,
        "the first bubble scrolled into view",
        DRAW_UNTIL_MAX,
        |cx| cx.debug_bounds("user-bubble-0").is_some(),
    );
    let bubble = cx
        .debug_bounds("user-bubble-0")
        .expect("the short bubble renders once scrolled to");
    assert_eq!(
        bubble.size.height,
        px(42.0),
        "one 22px line over 10px + 10px of padding"
    );
    assert_eq!(
        bubble.origin.x + bubble.size.width,
        transcript.origin.x + transcript.size.width - px(crate::theme::INSET),
        "the bubble ends at the transcript's content edge"
    );
}

/// The compaction marker is a real disclosure: it renders at the checkpoint
/// event - after the retained tail - with its own summary line, and pressing it
/// reveals the checkpoint body.
#[gpui::test]
fn the_compaction_marker_expands_to_the_checkpoint(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("compact-marker", 6);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            // A compaction folds all but the last message, leaving the
            // checkpoint as the request's first row.
            session.compacted = session.messages.len() - 1;
            session.compactions.push(crate::model::CompactionRecord {
                at: 0,
                items: 11,
                tokens: 4_096,
                summary: "## Current Work\n\n- the checkpoint body".to_string(),
                manual: true,
                // The seeded sessions end on an EMPTY assistant placeholder;
                // the checkpoint event sorts after the last real message.
                after: session.messages.len() - 1,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    // Scroll to the top so the marker is inside the windowed transcript.
    cx.update(|_, cx| {
        shell.update(cx, |shell, _| {
            shell.following_tail = false;
            shell.transcript_scroll.scroll_to_top_of_item(0);
        });
    });
    draw_until(cx, "the compaction marker renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("compaction-row-0").is_some()
    });
    // Bring the marker into the viewport: it sits at the checkpoint, which with
    // six turns of history is below the fold.
    cx.update(|_, cx| {
        shell.update(cx, |shell, _| {
            shell.transcript_scroll.scroll_to_top_of_item(0);
        });
    });
    // The reference anchors the marker at the checkpoint event, which is
    // appended after the whole retained tail: child 0 is the timestamp row,
    // then one child per message, then the marker. Scrolling to that child is
    // itself evidence that the marker sits at the end rather than above the
    // boundary.
    let checkpoint_child = cx.update(|_, cx| {
        let session = shell
            .read(cx)
            .state
            .active_session()
            .cloned()
            .expect("a session");
        assert_eq!(
            session.compactions.first().map(|record| record.after),
            Some(session.messages.len() - 1),
            "the record remembers the last real message at commit"
        );
        session.messages.len()
    });
    cx.update(|_, cx| {
        shell.update(cx, |shell, _| {
            shell
                .transcript_scroll
                .scroll_to_top_of_item(checkpoint_child);
        });
    });
    draw_until(cx, "the marker is in view", DRAW_UNTIL_MAX, |cx| {
        let Some(row) = cx.debug_bounds("compaction-row-0") else {
            return false;
        };
        let Some(pane) = cx.debug_bounds("transcript") else {
            return false;
        };
        row.origin.y >= pane.origin.y && row.center().y <= pane.origin.y + pane.size.height
    });
    // The header carries the count and the token figure the contract reports.
    assert!(
        cx.debug_bounds("compaction-title-0").is_some(),
        "the marker leads with its title"
    );
    assert!(
        cx.debug_bounds("compaction-summary-0").is_some(),
        "and its summary line"
    );
    assert!(
        cx.debug_bounds("compaction-body-0").is_none(),
        "the body is closed until the row is pressed"
    );

    let row = cx.debug_bounds("compaction-row-0").expect("the marker row");
    let centre = row.center();
    // The marker must be inside the viewport to be pressable: the harness
    // reports a clipped row's bounds happily while a click there is a silent
    // no-op, so the row is scrolled to first.
    let transcript = cx.debug_bounds("transcript").expect("the transcript pane");
    assert!(
        row.origin.y >= transcript.origin.y && centre.y <= transcript.origin.y + transcript.size.height,
        "the premise: the marker is inside the transcript viewport, row={row:?} pane={transcript:?}"
    );
    cx.simulate_click(centre, Modifiers::default());
    draw_until(cx, "the marker opened", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("compaction-body-0").is_some()
    });
    assert!(
        cx.update(|_, cx| shell.read(cx).compaction_open.contains(&0)),
        "the open state is recorded on the shell"
    );
    // Pressing again closes it, so the control is a toggle and not one-way.
    // The body just expanded, which moves the header, so its box is read again
    // rather than reusing the pre-expansion centre.
    let reopened = cx.debug_bounds("compaction-row-0").expect("the marker row");
    cx.simulate_click(reopened.center(), Modifiers::default());
    draw_until(cx, "the marker closed", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("compaction-body-0").is_none()
    });
    assert!(
        !cx.update(|_, cx| shell.read(cx).compaction_open.contains(&0)),
        "and the state is cleared"
    );
}

/// A session that has never been compacted draws no marker at all, so the row
/// is evidence of a real compaction rather than of every chat.
#[gpui::test]
fn an_uncompacted_session_draws_no_marker(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (_harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("compact-none", 4);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert!(
        cx.debug_bounds("compaction-row-0").is_none(),
        "no compaction means no marker"
    );
}

/// The checkpoint marker is a NORMAL transcript row at the event's own slot.
///
/// A checkpoint recorded after two messages must sit BETWEEN message 1 and
/// message 2 - read off the boxes of its neighbours, not merely "it exists".
/// The old shape pinned the row above the composer, where no transcript row
/// could ever be.
#[gpui::test]
fn the_compaction_marker_sits_between_the_messages_it_follows(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = AppState::with_store(scratch_store("compact-order"));
        tests_pin_reference_defaults(&mut state);
        // Detailed rows, so the marker's neighbours lay out inside the window
        // and their boxes can be read.
        state.settings.global.general.transcript_view = "verbose".to_string();
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            // Short turns: every row fits the window without scrolling, so the
            // order assertion is about the row sequence, not about the scroll.
            for turn in 0..3 {
                session
                    .messages
                    .push(ChatMessage::user(format!("turn {turn}")));
                session.messages.push(ChatMessage::assistant());
            }
            session.compactions.push(crate::model::CompactionRecord {
                at: 0,
                items: 7,
                tokens: 1_024,
                summary: "checkpoint body".to_string(),
                manual: true,
                // The checkpoint landed after two messages: the slot between
                // messages 1 and 2.
                after: 2,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    let _ = shell;
    draw_until(cx, "the marker renders in place", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("compaction-row-0").is_some()
    });
    let (marker, first, second, transcript) = (
        cx.debug_bounds("compaction-row-0")
            .expect("the checkpoint row"),
        cx.debug_bounds("message-footer-1")
            .expect("the footer of the message before the checkpoint"),
        // The next message is a USER row, which carries a bubble rather than a
        // footer: the footers belong to assistant turns.
        cx.debug_bounds("user-bubble-2")
            .expect("the message after the checkpoint"),
        cx.debug_bounds("transcript").expect("the transcript pane"),
    );
    assert!(
        first.origin.y < marker.origin.y,
        "the marker follows message 1: footer={first:?} marker={marker:?}"
    );
    assert!(
        marker.origin.y + marker.size.height <= second.origin.y,
        "and precedes message 2: marker={marker:?} bubble={second:?}"
    );
    assert!(
        marker.origin.y >= transcript.origin.y
            && marker.origin.y + marker.size.height
                <= transcript.origin.y + transcript.size.height,
        "the marker is a transcript row, not a floating slot: marker={marker:?} transcript={transcript:?}"
    );
}

/// Nothing is drawn between the transcript and the composer.
///
/// The compact command row used to be a pinned slot above the composer. It is a
/// transcript row now: its box lies inside the transcript pane and above the
/// composer card, and it follows the last message's footer.
#[gpui::test]
fn nothing_sits_between_the_transcript_and_the_composer(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = AppState::with_store(scratch_store("compact-pinned-gone"));
        tests_pin_reference_defaults(&mut state);
        state.settings.global.general.transcript_view = "verbose".to_string();
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            for turn in 0..2 {
                session
                    .messages
                    .push(ChatMessage::user(format!("turn {turn}")));
                session.messages.push(ChatMessage::assistant());
            }
            session.compact_command = Some(crate::model::CompactCommand {
                started_at: 0,
                outcome: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let _shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    draw_until(cx, "the command row renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("compact-command-row").is_some()
    });
    let row = cx
        .debug_bounds("compact-command-row")
        .expect("the compact command row");
    let transcript = cx.debug_bounds("transcript").expect("the transcript pane");
    let composer = cx.debug_bounds("composer-card").expect("the composer card");
    let last = cx
        .debug_bounds("message-footer-3")
        .expect("the last message's footer");
    assert!(
        row.origin.y >= transcript.origin.y
            && row.origin.y + row.size.height <= transcript.origin.y + transcript.size.height,
        "the command row is inside the transcript: row={row:?} transcript={transcript:?}"
    );
    assert!(
        last.origin.y < row.origin.y,
        "and follows the last message, in sequence: last={last:?} row={row:?}"
    );
    assert!(
        row.origin.y + row.size.height <= composer.origin.y,
        "nothing between the transcript and the composer: row={row:?} composer={composer:?}"
    );
    assert!(
        transcript.origin.y + transcript.size.height <= composer.origin.y,
        "the transcript itself ends above the composer: transcript={transcript:?} composer={composer:?}"
    );
}

/// The compaction rows are CHILDREN of the transcript scroller, not a fixed
/// slot between the transcript and the composer: scrolling moves their painted
/// bounds by the scroll delta.
///
/// This is the geometric proof the screenshot's "pinned block" asked for. A row
/// in a footer slot would keep the same window y while the transcript offset
/// changed; these rows must move with the content.
#[gpui::test]
fn the_compaction_rows_scroll_with_the_transcript(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("compact-scrolls", 30);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.compactions.push(crate::model::CompactionRecord {
                at: 0,
                items: 33,
                tokens: 4_219,
                summary: "checkpoint body".to_string(),
                manual: true,
                after: 2,
            });
            session.compact_command = Some(crate::model::CompactCommand {
                started_at: 0,
                outcome: Some(crate::model::CompactOutcome {
                    text: "Compaction could not produce a useful summary.".to_string(),
                    error: true,
                }),
            });
            // Rows AFTER the command: they keep it off the very end of the
            // scroller, so a small wheel step can move it without clipping.
            for seq in 1..=8 {
                state.mark_steering(
                    &id,
                    crate::state::Queued {
                        seq,
                        text: format!("pending steer {seq}"),
                        attachments: Vec::new(),
                    },
                );
            }
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    let messages = cx.update(|_, cx| {
        shell
            .read(cx)
            .state
            .active_session()
            .map(|session| session.messages.len())
            .expect("a session")
    });
    // Child 0 is the timestamp; one child per message; the marker at after=2
    // lands before message 2; the command row is the last child.
    let marker_child = 3usize;
    let command_child = 1 + messages + 1;
    // First position: scroll the row two children ABOVE the marker to the top so
    // the rows above the marker are BUILT and measured, then settle.
    cx.update(|_, cx| {
        shell.update(cx, |this, _| {
            this.following_tail = false;
            // One frame of "no previous max" keeps the tail bias from
            // re-engaging on the frame the scroll request lands: its growth
            // check would otherwise see the OLD at-the-end offset and snap back.
            this.tail_max = None;
            this.transcript_scroll
                .scroll_to_top_of_item(marker_child - 2);
        });
    });
    let (offset_before, marker_y_before) = draw_until_row_is_stable(
        cx,
        "the marker settles below the fold",
        &shell,
        "compaction-row-0",
    );
    // Second position: put the marker itself at the top. The scrolled distance
    // is the offset delta; the marker's painted y must move by that same N.
    cx.update(|_, cx| {
        shell.update(cx, |this, _| {
            this.following_tail = false;
            this.tail_max = None;
            this.transcript_scroll.scroll_to_top_of_item(marker_child);
        });
    });
    let (offset_after, marker_y_after) = draw_until_row_is_stable(
        cx,
        "the marker settles at the top",
        &shell,
        "compaction-row-0",
    );
    let scrolled = offset_after - offset_before;
    assert!(
        scrolled <= -20.0,
        "the premise: the transcript really scrolled N pixels: {scrolled}"
    );
    let marker_shift = marker_y_after - marker_y_before;
    assert!(
        (marker_shift - scrolled).abs() <= 1.5,
        "the marker moved with the content by the scroll delta: y {marker_y_before} -> {marker_y_after}, shift {marker_shift}, scrolled {scrolled}"
    );
    let marker = cx.debug_bounds("compaction-row-0").expect("the marker row");
    let transcript = cx.debug_bounds("transcript").expect("the transcript pane");
    assert!(
        marker.origin.y >= transcript.origin.y
            && marker.origin.y + marker.size.height <= transcript.origin.y + transcript.size.height,
        "and it is painted inside the scroller: marker={marker:?} transcript={transcript:?}"
    );

    // The command row is a scroller child too: a small wheel step moves its
    // painted y by the same delta. The rows after it are already built, so this
    // cannot pass through a remeasure instead of a scroll.
    cx.update(|_, cx| {
        shell.update(cx, |this, _| {
            this.following_tail = true;
            this.tail_max = None;
            this.transcript_scroll.scroll_to_bottom();
        });
    });
    draw_until(
        cx,
        "the transcript is at the bottom",
        DRAW_UNTIL_MAX,
        |cx| {
            let (offset, max) = cx.update(|_, cx| {
                let handle = &shell.read(cx).transcript_scroll;
                (handle.offset().y, handle.max_offset().y)
            });
            offset == -max && cx.debug_bounds("compact-command-row").is_some()
        },
    );
    let command_before = cx
        .debug_bounds("compact-command-row")
        .expect("the command row is visible above the pending rows");
    let (command_layout_before, offset_before) = cx.update(|_, cx| {
        let handle = &shell.read(cx).transcript_scroll;
        (
            handle
                .bounds_for_item(command_child)
                .expect("the scroller records the command child"),
            f32::from(handle.offset().y),
        )
    });
    let body = cx.debug_bounds("transcript").expect("the transcript");
    // One notch UP. The scroller applies it and the shell's own easing takes
    // over; several frames later both the offset and the painted row show the
    // movement, without depending on the animation's exact settle frame.
    cx.update(|window, cx| {
        window.dispatch_event(
            gpui_kit::PlatformInput::ScrollWheel(gpui_kit::ScrollWheelEvent {
                position: body.center(),
                delta: gpui_kit::ScrollDelta::Pixels(gpui_kit::point(px(0.0), px(60.0))),
                modifiers: Modifiers::default(),
                touch_phase: gpui_kit::TouchPhase::Moved,
            }),
            cx,
        );
    });
    for _ in 0..6 {
        cx.update(|window, cx| window.draw(cx).clear(cx));
    }
    let command_after = cx
        .debug_bounds("compact-command-row")
        .expect("the command row still paints");
    let (command_layout_after, offset_after) = cx.update(|_, cx| {
        let handle = &shell.read(cx).transcript_scroll;
        (
            handle
                .bounds_for_item(command_child)
                .expect("the scroller still records the command child"),
            f32::from(handle.offset().y),
        )
    });
    let scrolled = offset_after - offset_before;
    assert!(
        scrolled >= 20.0,
        "the premise: the wheel really scrolled N pixels: {scrolled}"
    );
    let command_shift = command_after.origin.y - command_before.origin.y;
    assert!(
        command_shift > px(0.0),
        "the command row moved DOWN with the upward scroll: {command_before:?} -> {command_after:?}"
    );
    // The geometry identity of a scroller child: painted = laid out + offset.
    // The row's laid-out slot may grow when a row above it is first measured,
    // so the delta is split into that remeasure and the scroll; a fixed footer
    // has no laid-out child at all and cannot satisfy this.
    let layout_delta = command_layout_after.origin.y - command_layout_before.origin.y;
    assert!(
        (command_shift - (layout_delta + px(scrolled))).abs() <= px(1.5),
        "the command row's painted y is its laid-out child plus the scroll offset: shift={command_shift:?} layout_delta={layout_delta:?} scrolled={scrolled}"
    );
}

/// A compaction performed at the END of the history is a row of the scroller,
/// AFTER the last message row - identified by the scroller's own recorded child
/// bounds, not merely by order in the rows vector.
#[gpui::test]
fn a_compaction_at_the_end_sits_after_the_last_message_inside_the_scroller(
    cx: &mut TestAppContext,
) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("compact-at-end", 6);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            // An idle compaction follows a REAL answer; the trailing empty
            // assistant placeholder of the seed is not a message the checkpoint
            // event follows, so give it the answer a finished turn would hold.
            if let Some(last) = session.messages.last_mut() {
                last.text = "the final answer".to_string();
            }
            let end = session.messages.len();
            session.compactions.push(crate::model::CompactionRecord {
                at: 0,
                items: 33,
                tokens: 4_219,
                summary: "checkpoint body".to_string(),
                manual: true,
                after: end,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, _| {
            this.following_tail = false;
            this.transcript_scroll.scroll_to_bottom();
        });
    });
    draw_until(cx, "the end marker renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("compaction-row-0").is_some()
            && cx.debug_bounds("message-footer-11").is_some()
    });
    let messages = cx.update(|_, cx| {
        shell
            .read(cx)
            .state
            .active_session()
            .map(|session| session.messages.len())
            .expect("a session")
    });
    let marker = cx
        .debug_bounds("compaction-row-0")
        .expect("the checkpoint row");
    let last_footer = cx
        .debug_bounds("message-footer-11")
        .expect("the last message's footer");
    let transcript = cx.debug_bounds("transcript").expect("the transcript pane");
    assert!(
        last_footer.origin.y < marker.origin.y,
        "the end marker follows the last message: footer={last_footer:?} marker={marker:?}"
    );
    assert!(
        marker.origin.y >= transcript.origin.y
            && marker.origin.y + marker.size.height
                <= transcript.origin.y + transcript.size.height,
        "and it is INSIDE the scroller, not between the scroller and the composer: marker={marker:?} transcript={transcript:?}"
    );
    // Parent-scroller identity: the scroller records a painted bound for every
    // child. The marker must be the child its own index names, with the same
    // box the frame painted. Order alone would pass for a footer slot too.
    let child = 1 + messages;
    let (recorded, offset) = cx.update(|_, cx| {
        let handle = &shell.read(cx).transcript_scroll;
        (
            handle
                .bounds_for_item(child)
                .expect("the scroller recorded the marker child"),
            handle.offset().y,
        )
    });
    // The scroller records a child's LAID OUT box; the painted box is that box
    // shifted by the current scroll offset. Equality under that shift is the
    // parent-scroller identity, which a footer slot can never satisfy.
    assert!(
        (recorded.origin.y + offset - marker.origin.y).abs() <= px(1.0)
            && (recorded.origin.x - marker.origin.x).abs() <= px(1.0)
            && (recorded.size.height - marker.size.height).abs() <= px(1.0),
        "the scroller's child {child} maps to this exact row at offset {offset:?}: recorded={recorded:?} painted={marker:?}"
    );
    assert!(
        cx.update(|_, cx| shell
            .read(cx)
            .transcript_scroll
            .bounds_for_item(child + 1)
            .is_none()),
        "nothing is rendered after the end marker inside the scroller"
    );
    let composer = cx.debug_bounds("composer-card").expect("the composer card");
    assert!(
        marker.origin.y + marker.size.height <= composer.origin.y
            && transcript.origin.y + transcript.size.height <= composer.origin.y,
        "the transcript ends above the composer, so no fixed slot sits between them: transcript={transcript:?} composer={composer:?}"
    );
}

/// move the transcript, so the tick is wired to the scroll handle, not just drawn.
#[gpui::test]
fn rail_tick_click_scrolls_the_transcript(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("rail", 30);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // The handle offset is the observable: bounds_for_item reports the laid out
    // position, which a scroll request does not rewrite.
    let scroll = |cx: &mut VisualTestContext, shell: &Entity<Shell>| {
        cx.update(|_, cx| {
            let handle = &shell.read(cx).transcript_scroll;
            (handle.offset().y, handle.max_offset().y)
        })
    };
    let (start, max) = scroll(cx, &shell);
    assert!(max > px(0.0), "the seeded transcript must be tall enough");
    assert_eq!(start, -max, "the transcript opens following the tail");

    let first: &str = Box::leak(String::from("turn-tick-0").into_boxed_str());
    let bounds = cx.debug_bounds(first).expect("the first rail tick");
    cx.simulate_click(bounds.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let (at_first, _) = scroll(cx, &shell);
    // Child 0 is the timestamp row, so turn 1 lands just below the top rather than
    // at offset 0 - and it must leave the end, where the transcript opened.
    assert!(
        at_first > start,
        "the first tick must move back up the transcript"
    );
    assert!(
        at_first > -px(150.0),
        "the first turn must land near the top, not at the end"
    );

    let last: &str = Box::leak(String::from("turn-tick-29").into_boxed_str());
    let bounds = cx.debug_bounds(last).expect("the last rail tick");
    cx.simulate_click(bounds.center(), Modifiers::default());
    // The transcript measures rows as they come into the prefetch band, so the
    // end it jumps to can grow for a frame or two after the click: assert that
    // it SETTLES at the end, not that it equals the height read before the jump.
    draw_until(
        cx,
        "the transcript settles at the end",
        DRAW_UNTIL_MAX,
        |cx| {
            cx.update(|_, cx| {
                let handle = &shell.read(cx).transcript_scroll;
                handle.offset().y == -handle.max_offset().y
            })
        },
    );
    assert!(
        cx.update(|_, cx| shell.read(cx).following_tail),
        "the newest tick keeps the transcript following the tail"
    );
}

