/// The chip is the whole permission decision: exactly three rows, each carrying
/// its one-line consequence; the current mode is marked; a lesser-or-equal mode
/// applies immediately; and Full access asks exactly once.
///
/// The rendered state is asserted through the value-encoded chip selector, and
/// each mode is written through the chip's own handler - so this proves the
/// control a reader presses, not only a pure table.
#[gpui::test]
fn the_chip_offers_three_modes_and_marks_the_current_one(cx: &mut TestAppContext) {
    init_test_app(cx);
    let home = scratch_home("chip-three-modes");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("chip-three-modes", 1);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    draw_until(
        cx,
        "the default Workspace Write chip renders",
        DRAW_UNTIL_MAX,
        |cx| cx.debug_bounds("permission-chip-workspace-write").is_some(),
    );

    let rows = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let effective = shell.state.effective();
        super::permission::permission_rows(Lang::En, &effective)
    });
    assert_eq!(rows.len(), 3, "the chip offers exactly three modes");
    let checked: Vec<&str> = rows
        .iter()
        .filter(|row| row.checked)
        .map(|row| row.mode.value())
        .collect();
    assert_eq!(
        checked,
        [crate::caps::WORKSPACE_WRITE],
        "a fresh session starts in Workspace Write, and only that row is marked"
    );
    for row in &rows {
        assert!(
            row.text.contains(" · "),
            "each row pairs the label with one consequence: {}",
            row.text
        );
    }

    // Full access: one confirmation, no second dialog, and Cancel preserves.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::FULL_ACCESS, cx)
        })
    });
    draw_until(cx, "the one confirmation draws", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("permission-confirm-enable").is_some()
    });
    assert!(
        cx.debug_bounds("permission-acknowledge").is_none(),
        "the confirmation has no acknowledgement step"
    );
    cx.update(|_, cx| shell.update(cx, |this, cx| this.permission_cancel_confirm(cx)));
    draw_until(
        cx,
        "cancel returns to the workspace chip",
        DRAW_UNTIL_MAX,
        |cx| cx.debug_bounds("permission-chip-workspace-write").is_some(),
    );

    // A lesser mode applies immediately and arms no gate.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::READ_ONLY, cx)
        })
    });
    draw_until(cx, "Read Only lands immediately", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("permission-chip-read-only").is_some()
    });
    assert!(
        cx.update(|_, cx| shell.read(cx).permission_confirm.is_none()),
        "a lesser mode never asks for confirmation"
    );

    // Full access, then straight back down: the narrowing is immediate.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::FULL_ACCESS, cx)
        })
    });
    draw_until(cx, "the gate is ready", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("permission-confirm-enable").is_some()
    });
    cx.update(|_, cx| shell.update(cx, |this, cx| this.permission_confirm_enable(cx)));
    draw_until(cx, "Full access renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("permission-chip-danger-full-access")
            .is_some()
    });
    assert!(
        cx.debug_bounds("permission-confirm-dialog").is_none(),
        "the gate closes and opens no second dialog"
    );
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::WORKSPACE_WRITE, cx)
        })
    });
    draw_until(
        cx,
        "Workspace Write narrows immediately",
        DRAW_UNTIL_MAX,
        |cx| cx.debug_bounds("permission-chip-workspace-write").is_some(),
    );
    assert!(
        cx.update(|_, cx| shell.read(cx).permission_confirm.is_none()),
        "narrowing from Full access asks nothing"
    );
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::WORKSPACE_WRITE,
        "the narrowed mode is the one on disk"
    );
}

/// The chip's three rows are a label and a SHORT qualifier, in the reference's
/// order, and none of them mentions the network.
///
/// The popup body is the kit's own menu item, which carries no debug selector,
/// so the observable is the row list the chip's render path builds
/// (`permission::permission_rows`) read from the live shell after the chip has
/// drawn - the same function, the same state. The detailed, derived sentence
/// the rows used to carry is still the Settings pane's
/// (`Mode::consequence`), and the permission unit tests pin it there.
#[gpui::test]
fn the_chips_three_rows_are_a_label_and_a_short_qualifier(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("permission-chip-short", 1);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    draw_until(cx, "the permission chip renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("permission-chip-workspace-write").is_some()
    });

    let rows = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let effective = shell.state.effective();
        super::permission::permission_rows(Lang::En, &effective)
    });
    assert_eq!(rows.len(), 3, "the chip offers exactly three modes");
    let texts: Vec<&str> = rows.iter().map(|row| row.text.as_str()).collect();
    assert_eq!(
        texts,
        [
            "Read Only · Nothing written, no commands.",
            "Workspace Write · Writes stay in this workspace.",
            "Full access · Writes anywhere.",
        ],
        "the menu is scannable: the label plus one short qualifier"
    );
    for row in &rows {
        assert!(
            row.text.chars().count() <= 48,
            "the row must stay short: {}",
            row.text
        );
        let lowered = row.text.to_lowercase();
        for banned in [
            "network",
            "egress",
            "sandbox",
            "proxy",
            "mcp",
            "browser",
            "allowlist",
            "shell",
            "terminal",
        ] {
            assert!(
                !lowered.contains(banned),
                "the row must not name {banned:?}: {}",
                row.text
            );
        }
    }
}

/// NEGATIVE: a preset that denies every destination cannot lengthen a menu row,
/// because the menu makes no network claim at all. The workspace file is ABSENT
/// here, which is exactly the state the old hardcoded "unrestricted" clause got
/// wrong; the deny-all preset's reach is still stated by the DETAILED sentence
/// in the Settings pane, which the permission unit tests pin.
#[gpui::test]
fn a_deny_all_preset_leaves_the_menu_rows_short(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("permission-chip-deny-all", 1);
        state.settings.global.presets.insert(
            "deny-all-network".to_string(),
            crate::settings::global::Preset {
                egress: Some(Vec::new()),
                ..crate::settings::global::Preset::default()
            },
        );
        state.settings.global.default_preset = "deny-all-network".to_string();
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    draw_until(cx, "the permission chip renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("permission-chip-workspace-write").is_some()
    });

    let (rows, preset) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let effective = shell.state.effective();
        (
            super::permission::permission_rows(Lang::En, &effective),
            effective.preset_id,
        )
    });
    assert_eq!(
        preset, "deny-all-network",
        "the premise: the session runs the deny-all preset"
    );
    assert_eq!(rows.len(), 3);
    let texts: Vec<&str> = rows.iter().map(|row| row.text.as_str()).collect();
    assert_eq!(
        texts,
        [
            "Read Only · Nothing written, no commands.",
            "Workspace Write · Writes stay in this workspace.",
            "Full access · Writes anywhere.",
        ],
        "a deny-all preset changes the reach, not the menu copy"
    );
}

/// The permission chip's menu writes through the same field the General pane's
/// choice row writes, and - NEW SEMANTICS - the write is a COMMIT.
///
/// The turn build reads the committed settings, so the old draft-only write
/// looked inert until somebody pressed Save. A selection now copies just
/// `workspace.agent.permission` across, saves it and adopts it, which is what
/// this test reads back: the committed tree, the draft that must agree with it,
/// and the file a relaunch would load.
#[gpui::test]
fn the_permission_chip_writes_the_mode_its_menu_offers(cx: &mut TestAppContext) {
    init_test_app(cx);
    let home = scratch_home("composer-permission-mode");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("composer-permission-mode", 1);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    let before = cx.update(|_, cx| {
        shell
            .read(cx)
            .state
            .settings
            .workspace
            .agent
            .permission
            .clone()
    });
    assert_eq!(
        before,
        crate::caps::WORKSPACE_WRITE,
        "the session starts on the committed default"
    );
    cx.update(|_, cx| {
        shell.update(cx, |shell, cx| {
            shell.set_permission(crate::caps::FULL_ACCESS, cx)
        });
    });
    let after = cx.update(|_, cx| {
        shell
            .read(cx)
            .state
            .settings
            .workspace
            .agent
            .permission
            .clone()
    });
    assert_eq!(
        after,
        crate::caps::FULL_ACCESS,
        "the write lands on the COMMITTED settings the turn build reads, not only the draft"
    );
    let drafted = cx.update(|_, cx| {
        shell
            .read(cx)
            .state
            .settings
            .workspace
            .agent
            .permission
            .clone()
    });
    assert_eq!(
        drafted,
        crate::caps::FULL_ACCESS,
        "and the draft agrees, so a later Save cannot resurrect the old mode"
    );
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::FULL_ACCESS,
        "the file a relaunch loads holds the chosen mode"
    );
}

/// Selecting Workspace Write on a Full-access session changes the NEXT TURN with
/// no Save and no dialog: the build reads the committed tree, and its tool set
/// and policy data carry the new mode.
#[gpui::test]
fn selecting_workspace_write_applies_to_the_next_turn_without_a_save(cx: &mut TestAppContext) {
    init_test_app(cx);
    let home = scratch_home("composer-permission-next-turn");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("composer-permission-next-turn", 1);
        state.settings.workspace.agent.permission = crate::caps::FULL_ACCESS.to_string();
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    // The menu row's own handler. Nothing opens the settings dialog and nothing
    // presses Save: the selection is the commit.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::WORKSPACE_WRITE, cx)
        })
    });
    let built = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let id = shell.state.active_id.clone().expect("a session");
        let choice = shell.state.session_choice(&id);
        crate::caps::build_agent(
            &shell.state.settings,
            &shell.state.vault,
            &choice,
            &shell.state.mcp,
        )
    });
    assert_eq!(
        built.policy.data().permission,
        crate::caps::WORKSPACE_WRITE,
        "the NEXT turn's policy data carries the selected mode"
    );
    let mut tools: Vec<String> = built
        .plugins
        .iter()
        .flat_map(|plugin| plugin.tools.clone())
        .collect();
    tools.sort();
    for expected in ["bash", "write_file", "edit_file", "read_file"] {
        assert!(
            tools.iter().any(|tool| tool == expected),
            "Workspace Write is the writable confined build, so {expected} is registered: {tools:?}"
        );
    }
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::WORKSPACE_WRITE,
        "and the choice persisted with no Save"
    );
}

/// A Read-only preset caps a Full-access choice: the chip shows the EFFECTIVE
/// (capped) mode with the ceiling annotation, the policy data hands Rego the
/// effective value, and a write is denied by the generated session-tier module.
#[gpui::test]
fn a_read_only_preset_caps_the_chip_policy_data_and_audit(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("composer-permission-capped", 1);
        // The chat asks for Full access; the preset it runs under is read-only.
        state.settings.workspace.agent.permission = crate::caps::WORKSPACE_WRITE.to_string();
        state.settings.global.presets.insert(
            "read-only".to_string(),
            crate::settings::global::Preset {
                permission: Some(crate::caps::READ_ONLY.to_string()),
                plugins: vec!["files".to_string()],
                ..crate::settings::global::Preset::default()
            },
        );
        state.settings.global.default_preset = "read-only".to_string();
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::FULL_ACCESS, cx)
        })
    });
    // NEW SEMANTICS: the read-only ceiling caps Full access, so there is no
    // widening to confirm and the request is applied without the danger gate.
    // This used to arm the dialog and confirm it; the chip still reads the same
    // resolution either way.
    let confirm = cx.update(|_, cx| shell.read(cx).permission_confirm.clone());
    assert_eq!(
        confirm, None,
        "a Full access the ceiling caps never arms the risk gate"
    );
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let resolution = cx.update(|_, cx| shell.read(cx).state.effective().permission);
    assert_eq!(
        resolution.requested,
        crate::caps::FULL_ACCESS,
        "the menu checkmark follows the reader's own choice"
    );
    assert_eq!(
        resolution.effective,
        crate::caps::READ_ONLY,
        "the ceiling wins"
    );
    assert_eq!(
        resolution.reduced_by.as_deref(),
        Some(crate::caps::READ_ONLY),
        "and the reduction names its cause"
    );
    let text = super::composer::permission_chip_text(Lang::En, &resolution);
    assert_eq!(
        text, "Read Only",
        "the chip states the mode the tools obey, in plain words"
    );
    assert!(
        super::composer::permission_choice_checked(&resolution, crate::caps::READ_ONLY),
        "the checkmark is on the mode the tools obey"
    );
    assert!(
        !super::composer::permission_choice_checked(&resolution, crate::caps::FULL_ACCESS),
        "not on a request the preset already caps"
    );
    let rows = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let effective = shell.state.effective();
        super::permission::permission_rows(Lang::En, &effective)
    });
    let full = rows
        .iter()
        .find(|row| row.mode.value() == crate::caps::FULL_ACCESS)
        .expect("the Full access row is still listed");
    assert!(!full.enabled, "a preset ceiling disables the row above it");
    assert_eq!(
        full.text, "Full access · Preset caps at Read Only.",
        "and the row says why it cannot be chosen"
    );
    assert!(
        cx.debug_bounds("permission-chip-read-only").is_some(),
        "the rendered chip carries the effective value"
    );

    let (built, denied_rule, audit_permission, requested) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let id = shell.state.active_id.clone().expect("a session");
        let choice = shell.state.session_choice(&id);
        let built = crate::caps::build_agent(
            &shell.state.settings,
            &shell.state.vault,
            &choice,
            &shell.state.mcp,
        );
        let root = built.policy.data().workspace_root.clone();
        let input = agent::policy::PolicyInput::new(
            "write_file",
            agent::policy::Action::Write,
            agent::policy::Target::path(root.join("notes.txt")),
        )
        .with_session(id)
        .with_preset("read-only");
        let decision = built.policy.check(&input);
        let rule = decision.rule.clone();
        let audit_permission = built
            .policy
            .denials()
            .last()
            .map(|entry| entry.permission.clone());
        (
            built,
            rule,
            audit_permission,
            shell.state.settings.workspace.agent.permission.clone(),
        )
    });
    assert_eq!(
        requested,
        crate::caps::FULL_ACCESS,
        "the REQUESTED mode is still Full access (effective != requested)"
    );
    assert_eq!(
        built.policy.data().permission,
        crate::caps::READ_ONLY,
        "the data handed to Rego is the EFFECTIVE mode, not the request"
    );
    assert_eq!(
        denied_rule.as_deref(),
        Some("session-read-only-write"),
        "the generated session-tier module is the one that refuses the write"
    );
    assert_eq!(
        audit_permission.as_deref(),
        Some(crate::caps::READ_ONLY),
        "and the audit row records the effective permission that refused it"
    );
    let mut tools: Vec<String> = built
        .plugins
        .iter()
        .flat_map(|plugin| plugin.tools.clone())
        .collect();
    tools.sort();
    assert!(
        !tools
            .iter()
            .any(|tool| tool == "write_file" || tool == "bash"),
        "the Rust registration floor still withholds the side-effecting tools: {tools:?}"
    );
    assert!(
        tools.iter().any(|tool| tool == "read_file"),
        "while the read side stays available: {tools:?}"
    );
}

/// Two panes, one fact: the General pane's permission row and the composer chip
/// both read the SAME resolution, so a preset ceiling cannot leave one reporting
/// the request and the other the effective value. The row still changes the
/// REQUEST, through the same persist path the chip uses.
#[gpui::test]
fn the_general_row_and_the_chip_report_one_effective_permission(cx: &mut TestAppContext) {
    init_test_app(cx);
    let home = scratch_home("general-permission-effective");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("general-permission-effective", 1);
        state.lang = Lang::En;
        // The request is Full access; the session's preset caps it at Read Only.
        state.settings.workspace.agent.permission = crate::caps::FULL_ACCESS.to_string();
        state.settings.global.presets.insert(
            "read-only".to_string(),
            crate::settings::global::Preset {
                permission: Some(crate::caps::READ_ONLY.to_string()),
                plugins: vec!["files".to_string()],
                ..crate::settings::global::Preset::default()
            },
        );
        state.settings.global.default_preset = "read-only".to_string();
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert!(
        cx.debug_bounds("permission-chip-read-only").is_some(),
        "the composer chip reports the capped effective mode"
    );

    cx.update(|window, cx| {
        shell.update(cx, |this, cx| {
            this.open_settings_at(
                section_index("general").expect("the General pane"),
                window,
                cx,
            )
        })
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert!(
        cx.debug_bounds("settings-pane").is_some(),
        "the General pane is on screen"
    );

    // The row's value line and the chip's text come from one resolution.
    let (row_value, row_selector, chip_text, resolution) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let resolution = shell.state.effective().permission.clone();
        let (row_value, row_selector) = shell.permission_row_display();
        (
            row_value,
            row_selector,
            super::composer::permission_chip_text(Lang::En, &resolution),
            resolution,
        )
    });
    assert_eq!(
        resolution.effective,
        crate::caps::READ_ONLY,
        "the premise: the ceiling lowers the request"
    );
    assert_eq!(
        resolution.requested,
        crate::caps::FULL_ACCESS,
        "the row still edits the request, which is Full access"
    );
    assert_eq!(
        row_value, chip_text,
        "the pane and the chip must render the same string"
    );
    assert_eq!(
        row_value, "Read Only",
        "the pane states the mode the tools obey, in plain words: {row_value:?}"
    );
    assert_eq!(
        row_selector, "set-perm-read-only",
        "the rendered row is drawn in the effective mode"
    );
    assert!(
        cx.debug_bounds("set-perm-read-only").is_some(),
        "so the pane's row is on screen reporting Read Only"
    );
    assert!(
        cx.debug_bounds("set-perm-full-access").is_none(),
        "and it never draws the uncapped request it is not obeying"
    );

    // Choosing a mode from the pane is still the immediate persist path: the
    // REQUEST changes even though the ceiling keeps the effective mode lower.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            super::settings::permission_action(this, crate::caps::WORKSPACE_WRITE, cx)
        })
    });
    assert_eq!(
        cx.update(|_, cx| {
            shell
                .read(cx)
                .state
                .settings
                .workspace
                .agent
                .permission
                .clone()
        }),
        crate::caps::WORKSPACE_WRITE,
        "the pane's pick writes the request at once"
    );
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::WORKSPACE_WRITE,
        "and it persisted with no Save"
    );
}

/// The widening gate follows the EFFECTIVE value. A preset ceiling that caps
/// Full access below it leaves nothing to widen, so the request is applied and
/// the ceiling notice explains the result; only a Full access that will actually
/// take effect arms the dialog, and cancelling it writes nothing.
#[gpui::test]
fn a_capped_full_access_skips_the_widening_gate(cx: &mut TestAppContext) {
    init_test_app(cx);
    let home = scratch_home("composer-permission-capped-gate");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("composer-permission-capped-gate", 1);
        state.lang = Lang::En;
        state.settings.workspace.agent.permission = crate::caps::READ_ONLY.to_string();
        state.settings.global.presets.insert(
            "capped".to_string(),
            crate::settings::global::Preset {
                permission: Some(crate::caps::WORKSPACE_WRITE.to_string()),
                plugins: vec!["files".to_string()],
                ..crate::settings::global::Preset::default()
            },
        );
        state.settings.global.default_preset = "capped".to_string();
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // A workspace-write ceiling under a Full-access request: no dialog.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::FULL_ACCESS, cx)
        })
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let (confirm, resolution, notice, requested) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (
            shell.permission_confirm.clone(),
            shell.state.effective().permission.clone(),
            shell.state.notice.clone(),
            shell.state.settings.workspace.agent.permission.clone(),
        )
    });
    assert_eq!(
        confirm, None,
        "a widening that cannot happen must not arm the gate"
    );
    assert!(
        cx.debug_bounds("permission-confirm-dialog").is_none(),
        "and no dialog is drawn"
    );
    assert_eq!(
        requested,
        crate::caps::FULL_ACCESS,
        "the chosen request is applied"
    );
    assert_eq!(
        resolution.effective,
        crate::caps::WORKSPACE_WRITE,
        "while the ceiling still caps what the session may do"
    );
    let expected_notice = crate::i18n::tr_args(
        Lang::En,
        "permission.ceilingNotice",
        &[
            (
                "requested",
                crate::i18n::tr(Lang::En, "permission.presetFullAccess"),
            ),
            (
                "ceiling",
                crate::i18n::tr(Lang::En, "permission.presetWorkspaceWrite"),
            ),
            (
                "effective",
                crate::i18n::tr(Lang::En, "permission.presetWorkspaceWrite"),
            ),
        ],
    );
    assert_eq!(
        notice.as_deref(),
        Some(expected_notice.as_str()),
        "and the existing ceiling notice says why the result stayed lower"
    );
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::FULL_ACCESS,
        "the request persisted without a Save"
    );

    // A Full-access ceiling genuinely widens, so the gate is still the route.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            if let Some(preset) = this.state.settings.global.presets.get_mut("capped") {
                preset.permission = Some(crate::caps::FULL_ACCESS.to_string());
            }
            this.request_permission(crate::caps::READ_ONLY, cx);
        })
    });
    let global = home.join("settings.toml");
    let workspace = crate::settings::workspace::WorkspaceSettings::path(&home);
    let before_global = std::fs::read(&global).expect("the global document was written");
    let before_workspace = std::fs::read(&workspace).expect("the workspace document was written");

    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::FULL_ACCESS, cx)
        })
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert_eq!(
        cx.update(|_, cx| shell.read(cx).permission_confirm.clone())
            .as_deref(),
        Some(crate::caps::FULL_ACCESS),
        "an effective widening still arms the gate"
    );
    assert!(
        cx.debug_bounds("permission-confirm-dialog").is_some(),
        "and draws it"
    );
    cx.update(|_, cx| shell.update(cx, |this, cx| this.permission_cancel_confirm(cx)));
    assert_eq!(
        std::fs::read(&global).expect("global document"),
        before_global,
        "cancel writes nothing, so the global document is byte-identical"
    );
    assert_eq!(
        std::fs::read(&workspace).expect("workspace document"),
        before_workspace,
        "and neither is the workspace document"
    );
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::READ_ONLY,
        "the cancelled offer leaves the stored request alone"
    );
}

/// The widening gate: cancel leaves the permission byte-identical on disk,
/// confirm persists it. The copy names what is loosened and what still holds.
#[gpui::test]
fn the_widening_gate_cancels_byte_identical_and_confirms(cx: &mut TestAppContext) {
    init_test_app(cx);
    let home = scratch_home("composer-permission-gate");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("composer-permission-gate", 1);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    // Start from a mode that is already on disk, so "unchanged" has a baseline.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::READ_ONLY, cx)
        })
    });
    let global = home.join("settings.toml");
    let workspace = crate::settings::workspace::WorkspaceSettings::path(&home);
    let before_global = std::fs::read(&global).expect("the global document was written");
    let before_workspace = std::fs::read(&workspace).expect("the workspace document was written");

    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::FULL_ACCESS, cx)
        })
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert!(
        cx.debug_bounds("permission-confirm-dialog").is_some(),
        "Full access still arms the risk gate"
    );
    cx.update(|_, cx| shell.update(cx, |this, cx| this.permission_cancel_confirm(cx)));
    assert_eq!(
        std::fs::read(&global).expect("global document"),
        before_global,
        "cancel writes nothing, so the global document is byte-identical"
    );
    assert_eq!(
        std::fs::read(&workspace).expect("workspace document"),
        before_workspace,
        "and neither is the workspace document"
    );
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::READ_ONLY,
        "the cancelled offer leaves the committed mode alone"
    );

    // Confirm on the second attempt: the mode persists.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::FULL_ACCESS, cx)
        })
    });
    cx.update(|_, cx| shell.update(cx, |this, cx| this.permission_confirm_enable(cx)));
    assert_eq!(
        reloaded_settings(&home).workspace.agent.permission,
        crate::caps::FULL_ACCESS,
        "a confirmed widening persists; the two buttons are the whole gate"
    );
}

/// A no-op selection writes nothing and says nothing: re-picking the mode the
/// committed tree already holds is not a save.
#[gpui::test]
fn reselecting_the_current_permission_writes_nothing(cx: &mut TestAppContext) {
    init_test_app(cx);
    let home = scratch_home("composer-permission-noop");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("composer-permission-noop", 1);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    // Persist a non-default mode first, so the "unchanged" comparison has files
    // to compare and cannot pass merely because nothing was ever written.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.request_permission(crate::caps::READ_ONLY, cx)
        })
    });
    let global = home.join("settings.toml");
    let workspace = crate::settings::workspace::WorkspaceSettings::path(&home);
    let before_global = std::fs::read(&global).expect("the global document was written");
    let before_workspace = std::fs::read(&workspace).expect("the workspace document was written");
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.state.notice = None;
            this.request_permission(crate::caps::READ_ONLY, cx);
        })
    });
    assert_eq!(
        std::fs::read(&global).expect("global document"),
        before_global,
        "a no-op selection writes no global document"
    );
    assert_eq!(
        std::fs::read(&workspace).expect("workspace document"),
        before_workspace,
        "and no workspace document"
    );
    assert_eq!(
        cx.update(|_, cx| shell.read(cx).state.notice.clone()),
        None,
        "and shows no notice"
    );
}

/// A refused permission write surfaces in the notice line and does not become
/// the mode in force: the chip must not claim what the file does not hold.
#[gpui::test]
fn a_refused_permission_write_is_reported_and_reverted(cx: &mut TestAppContext) {
    init_test_app(cx);
    let base = std::env::temp_dir().join(format!("bsh-permission-refused-{}", std::process::id()));
    std::fs::create_dir_all(&base).expect("a scratch directory");
    // A regular file where the settings DIRECTORY would have to be: the write
    // cannot create its parent, which is a failure no code path can paper over.
    let blocker = base.join("blocked");
    std::fs::write(&blocker, b"not a directory").expect("the blocker");
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("permission-refused", 1);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            // The notice is localized; pin the language so the assertion reads
            // the copy and not this machine's stored preference.
            this.state.lang = Lang::En;
            this.state.settings.save_root = Some(blocker.clone());
            this.request_permission(crate::caps::READ_ONLY, cx);
        })
    });
    let (permission, notice) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (
            shell.state.settings.workspace.agent.permission.clone(),
            shell.state.notice.clone(),
        )
    });
    assert_eq!(
        permission,
        crate::caps::WORKSPACE_WRITE,
        "a write that did not land must not become the committed mode"
    );
    assert!(
        notice.as_deref().is_some_and(
            |text| text.contains(crate::i18n::tr(Lang::En, "permission.saveFailed").as_str())
        ),
        "and the refusal is surfaced in the notice line, got {notice:?}"
    );
    let _ = std::fs::remove_dir_all(&base);
}

/// The full-access sentence names the consequence in the reader's words: the
/// write range, the released shell and the sandbox network allowlist. It is one
/// sentence, and none of it needs the level table to parse.
#[test]
fn the_full_access_sentence_names_the_consequences_without_the_level_table() {
    for lang in [Lang::En, Lang::Zh] {
        let text = crate::i18n::tr(lang, "permission.confirmDescription");
        assert_ne!(text, "permission.confirmDescription", "{lang:?} missing");
        assert_eq!(
            text.matches('.').count() + text.matches('。').count(),
            1,
            "the confirmation is one sentence: {text}"
        );
        for forbidden in [
            "level",
            "ceiling",
            "egress",
            "danger-full-access",
            "等级",
            "上限",
        ] {
            assert!(
                !text.contains(forbidden),
                "the sentence must not need the level table ({forbidden}): {text}"
            );
        }
    }
    let en = crate::i18n::tr(Lang::En, "permission.confirmDescription");
    for expected in ["write anywhere", "unconfined commands", "network allowlist"] {
        assert!(
            en.contains(expected),
            "the confirmation must name {expected:?}: {en:?}"
        );
    }
}

/// The reference's `formatDuration`: elapsed time in at most two adjacent
/// units, hours widest, floors to whole seconds.
#[test]
fn the_job_duration_takes_the_reference_units() {
    use crate::i18n::Lang;
    use crate::ui::header::job_duration;
    assert_eq!(job_duration(0, Lang::En), "0s");
    assert_eq!(job_duration(5_000, Lang::En), "5s");
    assert_eq!(job_duration(65_000, Lang::En), "1m 5s");
    assert_eq!(job_duration(3_725_000, Lang::En), "1h 2m");
    assert_eq!(job_duration(65_000, Lang::Zh), "1分5秒");
    assert_eq!(job_duration(86_400_000, Lang::En), "24h 0m");
}

/// The measured kill windows: an armed button waits three seconds for its
/// confirming press, and a failed stop keeps its hint for four - so three
/// seconds is already too long for the failure to still be showing.
#[test]
fn the_kill_phase_windows_are_the_measured_ones() {
    use crate::ui::header::{JobArm, JobPhase, JOB_KILL_ARM, JOB_KILL_FAILED};
    use std::time::{Duration, Instant};
    let at = Instant::now();
    let armed = JobArm {
        id: "job".to_string(),
        phase: JobPhase::Armed,
        at,
    };
    assert!(!armed.expired(at + JOB_KILL_ARM - Duration::from_millis(1)));
    assert!(armed.expired(at + JOB_KILL_ARM));
    let failed = JobArm {
        phase: JobPhase::Failed,
        ..armed.clone()
    };
    assert!(!failed.expired(at + JOB_KILL_ARM));
    assert!(failed.expired(at + JOB_KILL_FAILED));
}

/// The reference's two-press stop, driven through the handler's own seam: the
/// first press only arms, a press that arrives after the window re-arms rather
/// than stopping, and the confirming press inside it kills the job.
#[gpui::test]
fn the_job_stop_arms_then_stops_within_its_window(cx: &mut TestAppContext) {
    use crate::ui::header::{JobArm, JobPhase};
    use std::time::{Duration, Instant};
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("jobs-arm", 1);
        let session = state.active_id.clone().expect("an active session");
        state.settings.global.general.active_session = session.clone();
        spawn_background_job(&state, &session, "sleep 30");
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let id = cx.update(|_, cx| {
        harness
            .read(cx)
            .shell
            .read(cx)
            .state
            .background_jobs()
            .first()
            .expect("a background job")
            .id
            .clone()
    });
    let status = |cx: &mut VisualTestContext| {
        cx.update(|_, cx| {
            let shell = harness.read(cx).shell.read(cx);
            shell.state.jobs.job(&id).map(|job| job.status)
        })
    };
    let arm = |cx: &mut VisualTestContext| {
        cx.update(|_, cx| {
            harness
                .read(cx)
                .shell
                .read(cx)
                .jobs_arm
                .as_ref()
                .map(|arm| arm.phase)
        })
    };
    let press = |cx: &mut VisualTestContext, job: &str, at: Instant| {
        let job = job.to_string();
        cx.update(|_, cx| {
            let shell = harness.read(cx).shell.clone();
            shell.update(cx, |shell, cx| shell.press_job_kill_at(&job, at, cx));
        });
    };
    let expire = |cx: &mut VisualTestContext, at: Instant| {
        cx.update(|_, cx| {
            let shell = harness.read(cx).shell.clone();
            shell.update(cx, |shell, _cx| {
                shell.expire_job_arm(at);
            });
        });
    };
    let t0 = Instant::now();
    press(cx, &id, t0);
    assert_eq!(arm(cx), Some(JobPhase::Armed), "the first press only arms");
    assert_eq!(
        status(cx),
        Some(agent::jobs::JobStatus::Running),
        "and the job is still running"
    );
    expire(cx, t0 + Duration::from_millis(3000));
    assert_eq!(arm(cx), None, "the window disarms it");
    press(cx, &id, t0 + Duration::from_millis(5000));
    assert_eq!(
        arm(cx),
        Some(JobPhase::Armed),
        "a press after the window arms again instead of stopping"
    );
    assert_eq!(status(cx), Some(agent::jobs::JobStatus::Running));
    press(cx, &id, t0 + Duration::from_millis(5100));
    assert_eq!(arm(cx), None, "the confirming press clears the arming");
    assert_eq!(
        status(cx),
        Some(agent::jobs::JobStatus::Killed),
        "and kills the background job"
    );
    // A job that is already gone is the one failure a local stop can see, and
    // the reference keeps that hint for its own four-second window.
    press(cx, "ghost", t0);
    press(cx, "ghost", t0);
    assert_eq!(arm(cx), Some(JobPhase::Failed));
    expire(cx, t0 + Duration::from_millis(3999));
    assert!(
        arm(cx).is_some(),
        "three seconds is too soon for the hint to go"
    );
    expire(cx, t0 + Duration::from_millis(4000));
    assert_eq!(arm(cx), None);
    // The public shape the trigger and its count read.
    let _ = JobArm {
        id: id.clone(),
        phase: JobPhase::Armed,
        at: t0,
    };
    cx.update(|_, cx| {
        harness.read(cx).shell.read(cx).state.jobs.kill(&id);
    });
}

/// The rail is the reference's five cells plus the Vault, which BSH adds after
/// Account. The reference's own order is otherwise untouched.
