/// At the end of the scroll the last row stops SHORT of the pinned floor.
///
/// The tree's content used to end exactly on the account row's divider, so at max
/// offset the last row's lower edge sat on the hairline and read as sliced by the
/// pinned element. The content now carries a floor gap, and this pins both halves:
/// the list never overruns the account row, and its last row keeps the air.
#[gpui::test]
fn the_last_row_never_touches_the_pinned_floor(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("tree-floor", 1);
        let workspace = state.settings.global.general.active_workspace.clone();
        for n in 0..40 {
            let session = crate::model::Session::new(&workspace, format!("row {n}"));
            state.store.save(&session).expect("seed");
            state.store.insert(session);
        }
        state.store.sort();
        // A fixed id on the last row, so its selector is a literal this test can
        // ask for - `debug_bounds` only accepts `&'static str`.
        if let Some(last) = state.store.sessions.last_mut() {
            last.id = String::from("probe-last");
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| shell.update(cx, |this, cx| this.scroll_tree_by(f32::NEG_INFINITY, cx)));
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let tree = cx.debug_bounds("side-tree").expect("the tree");
    let account = cx.debug_bounds("account-row").expect("the account row");
    assert!(
        tree.bottom() <= account.top(),
        "the scroller never overruns the pinned row: tree ends at {}, account starts at {}",
        tree.bottom(),
        account.top()
    );
    let last = cx
        .debug_bounds("session-probe-last")
        .expect("the last row is painted at the end of the scroll");
    assert!(
        f32::from(tree.bottom() - last.bottom()) >= crate::theme::TREE_BOTTOM_INSET,
        "the last row keeps its floor gap: row ends at {}, floor at {} (gap {})",
        last.bottom(),
        tree.bottom(),
        f32::from(tree.bottom() - last.bottom())
    );
}

/// Deleting a chat parks it, and the bin can put it back.
///
/// The delete used to unlink the file, so a misclick was final. Now the envelope
/// is written BEFORE the row goes: a chat in the bin keeps its whole transcript,
/// its title and its workspace, and restoring rebuilds the file it came from.
#[test]
fn a_deleted_chat_is_parked_and_can_be_restored() {
    let mut state = state_with_turns("trash-session", 1);
    let id = state.new_session().expect("a chat");
    state.rename_session(&id, "keep me");
    let title = state.session_title(&id).expect("its title");

    assert!(state.delete_session(&id), "the delete happens");
    assert!(state.store.session(&id).is_none(), "the row is gone");

    let parked = state.trash();
    assert_eq!(parked.len(), 1, "and one item is in the bin");
    assert_eq!(parked[0].envelope.name, "keep me");
    assert_eq!(parked[0].kind(), Some(crate::trash::Kind::Session));

    let path = parked[0].path.clone();
    assert!(state.restore_trashed(&path), "restore succeeds");
    assert_eq!(
        state.session_title(&id).as_deref(),
        Some(title.as_str()),
        "the chat comes back with its title"
    );
    assert!(
        state.trash().is_empty(),
        "and the envelope is consumed, not copied"
    );
}

/// Purging a parked chat removes the envelope AND its Parquet log.
///
/// The log lives under the session's workspace directory, so the purge used to
/// name a directory that never existed and every deleted chat kept its
/// transcript and trajectory pages on disk.
#[test]
fn a_parked_chat_can_be_deleted_for_good() {
    let mut state = state_with_turns("trash-purge", 1);
    let id = state.new_session().expect("a chat");
    let workspace = state
        .store
        .session(&id)
        .expect("the chat")
        .workspace
        .clone();
    let log = crate::history::History::dir_for(&state.store.dir_for_workspace(&workspace), &id);
    std::fs::create_dir_all(&log).expect("the log directory");
    std::fs::write(log.join("msg-000.parquet"), b"page").expect("a transcript page");
    std::fs::write(log.join("traj-000.parquet"), b"page").expect("a trajectory page");

    assert!(state.delete_session(&id));
    let path = state.trash()[0].path.clone();
    assert!(path.exists(), "the envelope is on disk");

    assert!(state.purge_trashed(&path));

    assert!(!path.exists(), "purging unlinks it");
    assert!(
        !log.exists(),
        "and takes the transcript and trajectory pages with it: {}",
        log.display()
    );
    assert!(state.trash().is_empty());
    assert!(
        state.store.session(&id).is_none(),
        "and the chat does not come back"
    );
}

/// Purging a workspace from the bin removes the state bsh wrote into it.
#[test]
fn purging_a_workspace_removes_its_bsh_state() {
    let mut state = state_with_workspace_tree("trash-workspace-state");
    let id = state.settings.global.workspaces[0].id.clone();
    let root = std::path::PathBuf::from(&state.settings.global.workspaces[0].root);
    let bsh = root.join(".bsh");
    std::fs::create_dir_all(&bsh).expect("the state folder");
    std::fs::write(bsh.join("annotations.json"), b"[]").expect("a note file");
    let marker = root.join("keep.txt");
    std::fs::write(&marker, b"user content").expect("user content");

    assert!(state.delete_workspace(&id));
    let path = state.trash()[0].path.clone();
    assert!(state.purge_trashed(&path));

    assert!(
        !bsh.exists(),
        "the workspace state folder is gone: {}",
        bsh.display()
    );
    assert!(
        marker.exists(),
        "and the workspace's own files are untouched"
    );
}
/// Deleting a workspace parks its record, and restoring re-registers it with the
/// root it had.
#[test]
fn a_deleted_workspace_is_parked_and_can_be_restored() {
    let mut state = state_with_workspace_tree("trash-workspace");
    let id = state.settings.global.general.active_workspace.clone();
    let root = state
        .settings
        .global
        .workspaces
        .iter()
        .find(|workspace| workspace.id == id)
        .map(|workspace| workspace.root.clone())
        .expect("the seeded workspace");

    assert!(state.delete_workspace(&id), "the delete happens");
    assert!(
        !state
            .settings
            .global
            .workspaces
            .iter()
            .any(|workspace| workspace.id == id),
        "the row is gone"
    );
    let parked = state.trash();
    assert_eq!(parked.len(), 1, "and the record is in the bin");
    assert_eq!(parked[0].kind(), Some(crate::trash::Kind::Workspace));

    let path = parked[0].path.clone();
    assert!(state.restore_trashed(&path), "restore succeeds");
    let record = state
        .settings
        .global
        .workspaces
        .iter()
        .find(|workspace| workspace.id == id)
        .expect("the workspace is registered again");
    assert_eq!(record.root, root, "with the root it had");
    assert!(state.trash().is_empty());
}

/// The bin lives under the settings root, so a scratch configuration gets a
/// scratch bin - a test can never read or empty the reader's.
#[test]
fn the_bin_follows_the_settings_root() {
    let state = AppState::with_store(scratch_store("trash-root"));
    let root = state.settings.save_root.clone().expect("a scratch root");
    assert_eq!(state.settings.trash_dir(), root.join("trash"));
}

/// An archived row carries the same menu as a live one, with the archive cell
/// reading Unarchive.
///
/// The archived list used to offer only the restore arrow, so a chat in the
/// archive could not be renamed, forked, copied or deleted until it came back.
#[gpui::test]
fn the_archived_row_offers_the_session_menu(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (_harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("archived-menu", 1);
        let id = state.active_id.clone().expect("a session");
        state.archive_session(&id);
        // A fixed id, so the row's selectors are literals `debug_bounds` accepts.
        if let Some(session) = state.store.session_mut(&id) {
            session.id = String::from("menu-target");
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let row = cx
        .debug_bounds("archived-menu-target")
        .expect("the archived row");
    cx.simulate_mouse_move(
        row.center(),
        None::<gpui_kit::MouseButton>,
        Modifiers::default(),
    );
    let more = cx
        .debug_bounds("more-menu-target")
        .expect("the archived row's ellipsis");
    cx.simulate_click(more.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));

    for selector in [
        "session-menu-pin",
        "session-menu-rename",
        "session-menu-fork",
        "session-menu-copy",
        "session-menu-delete",
    ] {
        assert!(
            cx.debug_bounds(selector).is_some(),
            "the archived row's menu carries {selector}"
        );
    }
    assert!(
        cx.debug_bounds("session-menu-unarchive").is_some(),
        "and the archive cell offers the way back"
    );
    assert!(
        cx.debug_bounds("session-menu-archive").is_none(),
        "a chat in the archive cannot be archived again"
    );
}

/// An archived row starts its title where a live row does.
///
/// The archived list skipped the status-dot column, so its titles sat left of
/// every other session title - a different rank of thing, which is not what
/// "archived" means. Both kinds now lead with `TREE_ROW_LEAD`, the live rows with
/// their dot and the archived ones with an empty column of the same width.
#[gpui::test]
fn an_archived_row_is_indented_like_a_live_one(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (_harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("archived-indent", 1);
        // One live row and one archived row, each with a fixed id so the title
        // selectors are literals.
        let live = state.active_id.clone().expect("a session");
        if let Some(session) = state.store.session_mut(&live) {
            session.id = String::from("live-row");
        }
        let archived = state.new_session().expect("a second chat");
        state.archive_session(&archived);
        if let Some(session) = state.store.session_mut(&archived) {
            session.id = String::from("arch-row");
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let live = cx
        .debug_bounds("session-title-live-row")
        .expect("the live row's title");
    let archived = cx
        .debug_bounds("archived-title-arch-row")
        .expect("the archived row's title");
    assert_eq!(
        f32::from(live.left()),
        f32::from(archived.left()),
        "an archived title starts where a live one does"
    );
}

/// A mouse notch travels further than a trackpad's own delta, and a trackpad's
/// precise delta goes through 1:1.
///
/// "The scroll needs to be fast" was about the coarse wheel: one detent is a
/// whole line, and at 1:1 a long transcript takes dozens of them to cross.
#[test]
fn a_mouse_notch_is_gained_and_a_trackpad_is_not() {
    let line = px(20.0);
    let notch = super::transcript::wheel_pixels(
        &gpui_kit::ScrollDelta::Lines(gpui_kit::point(0.0, -3.0)),
        line,
    );
    let precise = super::transcript::wheel_pixels(
        &gpui_kit::ScrollDelta::Pixels(gpui_kit::point(px(0.0), px(-60.0))),
        line,
    );
    assert!(notch != 0.0, "the notch moves something");
    assert!(
        notch.abs() > 60.0,
        "and further than its raw pixels: {notch}"
    );
    assert_eq!(
        precise, -60.0,
        "a trackpad's precise delta is passed through untouched"
    );
}

/// The turn rail's last mark must be reachable: with more marks than the frame
/// holds, the rail keeps the newest one in view, so a click near the frame's
/// bottom lands on the mark that jumps to the latest turn instead of on a sliver
/// painted outside the box that hit-tests it.
#[gpui::test]
fn the_last_turn_tick_is_reachable(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("rail-last", 60);
        tests_pin_reference_defaults(&mut state);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let (frame, offset, max) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (
            shell.rail_scroll.bounds(),
            f32::from(shell.rail_scroll.offset().y),
            f32::from(shell.rail_scroll.max_offset().y),
        )
    });
    assert!(max > 0.0, "sixty turns overflow the frame: max {max}");
    assert_eq!(
        offset, -max,
        "the rail rests at its bottom, so the newest mark is in view"
    );

    // Where the last mark lands inside the visible band.
    let pitch = crate::theme::TURN_PITCH;
    let inset = crate::theme::TURN_RAIL_INSET;
    let mark_y = f32::from(frame.bottom()) - inset - pitch / 2.0;
    assert!(
        mark_y < f32::from(frame.bottom()) && mark_y > f32::from(frame.top()),
        "the last mark is inside the frame: {mark_y} in {}..{}",
        f32::from(frame.top()),
        f32::from(frame.bottom())
    );

    // The mark the reader presses is the one ON SCREEN: the last tick's laid-out
    // position, shifted by the rail's scroll, has to fall inside the frame. That
    // is the defect this guards - a mark painted below the frame's own box still
    // reports bounds and still refuses the click.
    let tick = cx.debug_bounds("turn-tick-59").expect("the last tick");
    let visible_y = f32::from(tick.top()) + offset;
    assert!(
        visible_y >= f32::from(frame.top()) - 0.5
            && visible_y + pitch <= f32::from(frame.bottom()) + 0.5,
        "the last mark is inside the frame once scrolled: {visible_y} in {}..{}",
        f32::from(frame.top()),
        f32::from(frame.bottom())
    );
}

/// The rail's marks must actually receive the click. This presses the rail at
/// the point where a mark is drawn and asserts the transcript jumps - once for
/// the first mark and once for the last, because the symptom was that marks drew
/// but did nothing.
#[gpui::test]
fn the_rail_marks_receive_the_click(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("rail-click", 30);
        tests_pin_reference_defaults(&mut state);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let frame = cx.update(|_, cx| shell.read(cx).rail_scroll.bounds());
    let pitch = crate::theme::TURN_PITCH;
    let inset = crate::theme::TURN_RAIL_INSET;
    // The centre of the first mark, from the frame's top.
    let first_y = f32::from(frame.top()) + inset + pitch / 2.0;
    let x = f32::from(frame.right()) - 8.0;

    // Park the transcript at the newest turn so a jump to the first one moves.
    let before = cx.update(|_, cx| f32::from(shell.read(cx).transcript_scroll.offset().y));
    cx.simulate_click(gpui_kit::point(px(x), px(first_y)), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let after = cx.update(|_, cx| f32::from(shell.read(cx).transcript_scroll.offset().y));
    assert!(
        after > before + 1.0,
        "pressing a mark moves the transcript: {before} -> {after}"
    );
}

/// Pressing the NEWEST mark is the way back to the live end: it re-engages the
/// tail pin, so the chat follows again. Every other mark must leave the pin off,
/// or a jump up the transcript would be undone by the next frame.
#[gpui::test]
fn the_newest_mark_reengages_the_tail(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("rail-tail", 30);
        tests_pin_reference_defaults(&mut state);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // Leave the tail the way a reader does, then press the newest mark.
    cx.update(|_, cx| {
        shell.update(cx, |this, _| {
            this.following_tail = false;
            this.transcript_scroll.scroll_to_top_of_item(0);
        });
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let left_tail = cx.update(|_, cx| shell.read(cx).following_tail);
    assert!(!left_tail, "the reader left the tail");

    // The newest mark, from its own laid-out box: with thirty turns the frame
    // holds every mark, so it is on screen - the half a pixel comparison cannot
    // answer. The press itself goes through the same method the mark's click
    // calls, because a 28px overlay does not take a synthetic click reliably.
    let last = cx.debug_bounds("turn-tick-29").expect("the newest mark");
    let frame = cx.update(|_, cx| shell.read(cx).rail_scroll.bounds());
    assert!(
        last.top() >= frame.top() - px(0.5) && last.bottom() <= frame.bottom() + px(0.5),
        "the newest mark is inside the frame"
    );
    cx.update(|_, cx| {
        shell.update(cx, |this, _| this.jump_to_turn(1 + 58, true));
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let (pinned, offset, max) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (
            shell.following_tail,
            f32::from(shell.transcript_scroll.offset().y),
            f32::from(shell.transcript_scroll.max_offset().y),
        )
    });
    assert!(pinned, "the newest mark re-engages the tail");
    assert_eq!(offset, -max, "and lands at the live end");
}

/// At the tail the rail highlights the NEWEST mark: the last mark names the turn
/// the reader is looking at, so leaving the turn above it lit made the final mark
/// look dead beside a chat that had already ended.
#[gpui::test]
fn the_rail_highlights_the_newest_mark_at_the_tail(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("rail-active", 30);
        tests_pin_reference_defaults(&mut state);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let (turns, active) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let turns = shell.turn_indices();
        (turns.len(), shell.visible_turn(&turns))
    });
    assert!(turns > 1, "the rail needs more than one turn");
    assert_eq!(
        active,
        Some(turns - 1),
        "at the tail the newest mark is the active one"
    );

    // Scrolled to the top, the active mark is the first one again.
    cx.update(|_, cx| {
        shell.update(cx, |this, _| {
            this.following_tail = false;
            this.transcript_scroll.scroll_to_top_of_item(0);
        });
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let active = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let turns = shell.turn_indices();
        shell.visible_turn(&turns)
    });
    assert_eq!(active, Some(0), "and at the top the first mark is");
}
/// REPRODUCTION, not a passing test: with an overflowing rail (more marks than
/// the 420px frame holds) the hover preview does not draw at all - not for the
/// newest mark and not for a middle one - while the same hover works when every
/// mark fits. `rail_hover` IS set, so the state is right and the card is what is
/// missing from the drawn frame.
///
/// Left ignored rather than deleted: it is the exact case a reader reported
/// ("hover the last one, no card, but the others have one") and the next round
/// should start here rather than from a guess.
#[gpui::test]
fn an_overflowing_rail_draws_the_hover_preview(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("rail-overflow-hover", 60);
        tests_pin_reference_defaults(&mut state);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let middle = cx
        .debug_bounds("turn-tick-50")
        .expect("a mark near the tail");
    // Marks are addressed by ORDINAL, so 60 turns run turn-tick-0 .. turn-tick-59
    // whatever their message indices are.
    cx.simulate_mouse_move(
        middle.center(),
        None::<gpui_kit::MouseButton>,
        Modifiers::default(),
    );
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert_eq!(
        cx.update(|_, cx| shell.read(cx).rail_hover),
        Some(50),
        "the hover reaches the rail"
    );
    assert!(
        cx.debug_bounds("turn-preview").is_some(),
        "and the overflowing rail still draws the card"
    );

    // And the NEWEST mark, at the frame's bottom edge of an overflowing rail.
    let newest = cx.debug_bounds("turn-tick-59").expect("the newest mark");
    cx.simulate_mouse_move(
        newest.center(),
        None::<gpui_kit::MouseButton>,
        Modifiers::default(),
    );
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert_eq!(
        cx.update(|_, cx| shell.read(cx).rail_hover),
        Some(59),
        "the newest mark takes the hover"
    );
    assert!(
        cx.debug_bounds("turn-preview").is_some(),
        "and an overflowing rail previews it too"
    );
}
/// The Duration toggle is the strip's measure: OFF draws every block at the
/// reference's fixed equal width, ON lays the lanes out against ONE shared time
/// axis, so x is when an event started and width is how long it took.
///
/// The numbers below are the user's own example, in geometry rather than in
/// prose: turn 1's call runs 9s from t=1s, turn 2's runs 0.2s from t=11s, so the
/// slow block must be 45x the quick one, start at the track's left edge, and
/// leave the ten seconds before the second block empty.
#[gpui::test]
fn the_duration_lanes_are_time_proportional(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("traj-time-lanes", 2);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            // Turn 1: one 9s call starting at t=1s. Turn 2: one 0.2s call
            // starting ten seconds later. Both carry a start, which is what
            // makes the shared axis meaningful.
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "bash".to_string(),
                args: "{}".to_string(),
                output: Some("slow".to_string()),
                ms: Some(9_000),
                at: Some(1_000),
            });
            session.messages[3].tools.push(crate::model::ToolEvent {
                name: "bash".to_string(),
                args: "{}".to_string(),
                output: Some("quick".to_string()),
                ms: Some(200),
                at: Some(11_000),
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.state.tab = Tab::Trajectory;
            cx.notify();
        });
    });
    draw_until(cx, "the lane blocks draw", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("traj-cell-hit-2").is_some()
            && cx.debug_bounds("traj-cell-hit-5").is_some()
            && cx.debug_bounds("traj-lane-tools").is_some()
    });

    // The event log is [user0, assistant1, tool2, user3, assistant4, tool5]:
    // the two tool blocks are indices 2 and 5.
    let cell = |cx: &mut VisualTestContext, index: usize| {
        let selector: &'static str = Box::leak(format!("traj-cell-hit-{index}").into_boxed_str());
        let bounds = cx.debug_bounds(selector).expect("a lane block");
        (f32::from(bounds.origin.x), f32::from(bounds.size.width))
    };

    // OFF is the reference's equal-width reading: 8px blocks, identical despite
    // a 45x difference in duration - but still POSITIONED by when they happened.
    let (slow_x0, slow_w) = cell(cx, 2);
    let (quick_x0, quick_w) = cell(cx, 5);
    assert!(
        (slow_w - 8.0).abs() <= 0.5 && (quick_w - 8.0).abs() <= 0.5,
        "equal width draws the measured 8px blocks: {slow_w} {quick_w}"
    );
    assert!(!cx.update(|_, cx| shell.read(cx).traj_actual_duration));
    // The two calls happened 10 seconds apart, so their blocks must not sit on
    // top of each other: size is equal, POSITION is still the clock. This is the
    // bug a reader saw as one solid bar per lane.
    let track0 = cx.debug_bounds("traj-lane-tools").expect("the tools lane");
    let track0_left = f32::from(track0.origin.x);
    let track0_w = f32::from(track0.size.width);
    assert!(
        quick_x0 - slow_x0 > 1.0,
        "equal-width blocks keep their real positions: {slow_x0} vs {quick_x0}"
    );
    assert!(
        (slow_x0 - track0_left).abs() <= 1.0,
        "the first block still opens at the axis start: {slow_x0} vs {track0_left}"
    );
    // 1_000 .. 11_200ms is the axis, so the quick call sits 10/10.2 of the
    // way along it: equal width changes the SIZE, never the placement.
    let span0 = 10_200.0f32;
    assert!(
        (quick_x0 - (track0_left + track0_w * (10_000.0 / span0))).abs() <= 2.0,
        "and the second sits ten seconds along the axis: {quick_x0} vs {}",
        track0_left + track0_w * (10_000.0 / span0)
    );

    // Turning Duration ON must re-lay the strip in the frame the test observes.
    let toggle = cx
        .debug_bounds("traj-duration")
        .expect("the Duration toggle");
    cx.simulate_click(toggle.center(), Modifiers::default());
    draw_until(
        cx,
        "Duration mode becomes real-time",
        DRAW_UNTIL_MAX,
        |cx| {
            cx.update(|_, cx| shell.read(cx).traj_actual_duration)
                && cx
                    .debug_bounds("traj-cell-hit-2")
                    .is_some_and(|bounds| f32::from(bounds.size.width) > 100.0)
        },
    );

    let track = cx.debug_bounds("traj-lane-tools").expect("the tools lane");
    let track_left = f32::from(track.origin.x);
    let track_w = f32::from(track.size.width);
    let (slow_x, slow_w) = cell(cx, 2);
    let (quick_x, quick_w) = cell(cx, 5);

    // Axis: 1_000 .. 11_200ms (the slow call ends at 10_000, the quick one at
    // 11_200), so 9_000ms and 200ms are 0.882 and 0.0196 of the lane.
    let span = 10_200.0f32;
    assert!(
        (slow_w / quick_w - 45.0).abs() < 0.5,
        "the 9s block is 45x the 0.2s block: {slow_w} vs {quick_w}"
    );
    assert!(
        (slow_x - track_left).abs() <= 1.0,
        "the first block starts at the axis start: {slow_x} vs {track_left}"
    );
    assert!(
        (slow_w - track_w * (9_000.0 / span)).abs() <= 2.0,
        "width is duration over the common span: {slow_w} vs {}",
        track_w * (9_000.0 / span)
    );
    assert!(
        (quick_x - (track_left + track_w * (10_000.0 / span))).abs() <= 2.0,
        "the second block sits ten seconds along the axis: {quick_x} vs {}",
        track_left + track_w * (10_000.0 / span)
    );

    // The idle stretch between the calls is EMPTY: no block occupies it, and the
    // next block starts where its own event started rather than where the
    // previous one ended.
    let gap = quick_x - (slow_x + slow_w);
    assert!(
        gap > 20.0,
        "the ten-second wait is visible as empty space: {gap}"
    );
    assert!(
        (gap - track_w * (1_000.0 / span)).abs() <= 2.0,
        "the gap is the 1s between the calls: {gap} vs {}",
        track_w * (1_000.0 / span)
    );

    // One common axis: events that start together share an x across lanes. The
    // assistant row that opened turn 2 and its tool both start at t=11s; the
    // turn-1 pair both start at t=1s.
    let (model_x, _) = cell(cx, 4);
    assert!(
        (model_x - quick_x).abs() <= 1.0,
        "the model and tool lanes share the axis: {model_x} vs {quick_x}"
    );
    let (first_model_x, _) = cell(cx, 1);
    assert!(
        (first_model_x - slow_x).abs() <= 1.0,
        "both turn-1 rows start at the axis start: {first_model_x} vs {slow_x}"
    );

    // And switching back restores the equal-width reading, so the toggle is a
    // real measure rather than a one-way flag.
    let toggle = cx
        .debug_bounds("traj-duration")
        .expect("the Duration toggle");
    cx.simulate_click(toggle.center(), Modifiers::default());
    draw_until(
        cx,
        "Duration mode becomes equal-width again",
        DRAW_UNTIL_MAX,
        |cx| {
            !cx.update(|_, cx| shell.read(cx).traj_actual_duration)
                && cx
                    .debug_bounds("traj-cell-hit-2")
                    .is_some_and(|bounds| f32::from(bounds.size.width) <= 9.0)
        },
    );
    let (_, slow_w) = cell(cx, 2);
    let (_, quick_w) = cell(cx, 5);
    assert!(
        (slow_w - quick_w).abs() <= 1.5,
        "equal width draws both the same again: {slow_w} {quick_w}"
    );
}

/// An event with no recorded start still draws in Duration mode: it is placed
/// at the nearest known instant in its lane and keeps the two-pixel minimum
/// width, rather than being dropped from the strip.
#[gpui::test]
fn an_untimed_event_still_draws_in_duration_mode(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("traj-untimed", 2);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            // A timed call, then a record written before the clock existed.
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "bash".to_string(),
                args: "{}".to_string(),
                output: Some("timed".to_string()),
                ms: Some(1_000),
                at: Some(1_000),
            });
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "read_file".to_string(),
                args: "{}".to_string(),
                output: Some("no clock".to_string()),
                ms: None,
                at: None,
            });
            session.messages[3].tools.push(crate::model::ToolEvent {
                name: "bash".to_string(),
                args: "{}".to_string(),
                output: Some("later".to_string()),
                ms: Some(200),
                at: Some(11_000),
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.state.tab = Tab::Trajectory;
            this.traj_actual_duration = true;
            this.traj_actual_time = true;
            cx.notify();
        });
    });
    // The log is [user0, assistant1, tool2, tool3, user4, assistant5, tool6]:
    // tool3 is the untimed one.
    draw_until(cx, "the untimed block draws", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("traj-cell-hit-3").is_some()
    });
    let block = cx
        .debug_bounds("traj-cell-hit-3")
        .expect("the untimed block");
    let width = f32::from(block.size.width);
    let x = f32::from(block.origin.x);
    assert!(
        width >= 1.5,
        "the untimed event keeps a minimum-width block: {width}"
    );
    let timed = cx
        .debug_bounds("traj-cell-hit-2")
        .expect("its timed neighbour");
    assert!(
        (x - f32::from(timed.origin.x)).abs() <= 1.0,
        "it is placed at the nearest known time: {x} vs {}",
        f32::from(timed.origin.x)
    );
    // Every lane event still draws: a fallback never silently drops a row.
    for index in 0..7 {
        let selector: &'static str = Box::leak(format!("traj-cell-hit-{index}").into_boxed_str());
        assert!(
            cx.debug_bounds(selector).is_some(),
            "event {index} is not omitted from the strip"
        );
    }
}

/// A timeline block is a way BACK to the record it stands for: pressing it
/// selects that row and opens its detail panel, which is the reference's own
/// `onRecordSelect`. Before this the strip was a picture with no handle.
#[gpui::test]
fn a_timeline_block_selects_its_record(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("traj-block-click", 2);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "bash".to_string(),
                args: "{\"command\":\"ls\"}".to_string(),
                output: Some("a.txt".to_string()),
                ms: Some(1_000),
                at: Some(1_000),
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.state.tab = Tab::Trajectory;
            this.traj_select = None;
            cx.notify();
        });
    });
    draw_until(cx, "the bar renders a block", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("traj-cell-hit-0").is_some()
    });
    assert!(
        cx.update(|_, cx| shell.read(cx).traj_select.is_none()),
        "the premise: nothing is selected yet"
    );
    let block = cx.debug_bounds("traj-cell-hit-0").expect("the block");
    cx.simulate_click(block.center(), Modifiers::default());
    draw_until(cx, "the record is selected", DRAW_UNTIL_MAX, |cx| {
        cx.update(|_, cx| shell.read(cx).traj_select == Some(0))
    });
    assert_eq!(
        cx.update(|_, cx| shell.read(cx).traj_tab),
        0,
        "and the detail panel opens on its summary"
    );
}

/// The horizontal painted span of one debug-selected element, in window
/// coordinates.
fn painted_span(cx: &mut VisualTestContext, selector: &'static str) -> (f32, f32) {
    let bounds = cx
        .debug_bounds(selector)
        .unwrap_or_else(|| panic!("{selector} renders"));
    (
        f32::from(bounds.origin.x),
        f32::from(bounds.origin.x + bounds.size.width),
    )
}

/// Boot the shell on the Trajectory tab with these tool calls planted on the
/// two assistant turns `state_with_turns` seeds (messages 1 and 3).
///
/// `calls` is `(message, started-at ms, duration ms)`; a timed tool also
/// anchors its assistant row, which is why the model lane has blocks too.
fn boot_trajectory<'a>(
    cx: &'a mut TestAppContext,
    label: &'static str,
    calls: &[(usize, u64, Option<u64>)],
    duration_mode: bool,
) -> (Entity<Shell>, &'a mut VisualTestContext) {
    init_test_app(cx);
    let calls = calls.to_vec();
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns(label, 2);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            for (message, at, ms) in calls {
                session.messages[message].tools.push(ToolEvent {
                    name: "bash".to_string(),
                    args: "{}".to_string(),
                    output: Some("ok".to_string()),
                    ms,
                    at: Some(at),
                });
            }
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.state.tab = Tab::Trajectory;
            this.traj_actual_duration = duration_mode;
            this.traj_actual_time = true;
            cx.notify();
        })
    });
    (shell, cx)
}

/// Draw until the lane track has measured itself and the strip's blocks are on
/// screen, then draw the one frame that APPLIES the measured width.
///
/// The measurement lands during prepaint, after the frame that will paint it
/// was built, so a settled pixel assertion is always one frame behind the
/// predicate.
fn settle_lanes(cx: &mut VisualTestContext, shell: &Entity<Shell>) {
    let shell = shell.clone();
    draw_until(
        cx,
        "the lane track is measured and its blocks draw",
        DRAW_UNTIL_MAX,
        |cx| {
            cx.update(|_, cx| shell.read(cx).traj_lane_w.get())
                .is_some()
                && cx.debug_bounds("traj-lane-tools").is_some()
                && cx.debug_bounds("traj-strip").is_some()
                && cx.debug_bounds("traj-cell-hit-2").is_some()
        },
    );
    cx.update(|window, cx| window.draw(cx).clear(cx));
}

/// Assert every block the log projects into a lane is inside its lane's track
/// and inside the strip's own bounds, on both axes.
///
/// The lane is derived from the event's own kind, so this covers Input, Model
/// and Tools rather than whichever lane the test happened to seed.
fn assert_blocks_inside(cx: &mut VisualTestContext, shell: &Entity<Shell>, tag: &str) {
    let strip = cx.debug_bounds("traj-strip").expect("the strip renders");
    let strip_left = f32::from(strip.origin.x);
    let strip_right = strip_left + f32::from(strip.size.width);
    let strip_top = f32::from(strip.origin.y);
    let strip_bottom = strip_top + f32::from(strip.size.height);
    let events = cx.update(|_, cx| crate::ui::trajectory::events(shell.read(cx)));
    let mut checked = 0usize;
    for (index, event) in events.iter().enumerate() {
        let lane: &'static str = match event.kind {
            crate::ui::trajectory::Kind::User => "traj-lane-input",
            crate::ui::trajectory::Kind::Assistant => "traj-lane-model",
            crate::ui::trajectory::Kind::Tool => "traj-lane-tools",
            _ => continue,
        };
        let track = cx
            .debug_bounds(lane)
            .unwrap_or_else(|| panic!("{tag}: {lane} renders"));
        let track_left = f32::from(track.origin.x);
        let track_right = track_left + f32::from(track.size.width);
        let selector: &'static str = Box::leak(format!("traj-cell-hit-{index}").into_boxed_str());
        let cell = cx
            .debug_bounds(selector)
            .unwrap_or_else(|| panic!("{tag}: event {index} draws a block"));
        let left = f32::from(cell.origin.x);
        let right = left + f32::from(cell.size.width);
        let top = f32::from(cell.origin.y);
        let bottom = top + f32::from(cell.size.height);
        assert!(
            left >= track_left - 1.0,
            "{tag}: event {index} stays off the lane's left edge: {left} vs {track_left}"
        );
        assert!(
            right <= track_right + 1.0,
            "{tag}: event {index} stays inside the lane: {right} vs {track_right}"
        );
        assert!(
            left >= strip_left - 1.0
                && right <= strip_right + 1.0
                && top >= strip_top - 1.0
                && bottom <= strip_bottom + 1.0,
            "{tag}: event {index} is inside the strip's own bounds: cell {cell:?}, strip {strip:?}"
        );
        checked += 1;
    }
    assert!(
        checked >= 6,
        "{tag}: the sweep saw every lane's blocks, not none: {checked}"
    );
}

/// A lane whose last event ends EXACTLY on the shared axis end paints its
/// right edge on the track's own right edge.
///
/// The axis is 1s..6s: the second call starts at t=5s and takes 1s, so its
/// fraction ends at 1.0 while its width is a real 20% of the axis. That block
/// never needed the floor, and the clamp must not shift it: its right edge is
/// within 1px of the track's right edge, and its width is still the duration's
/// share. The overflow cases (the floor and the 8px equal width) are the two
/// tests below.
#[gpui::test]
fn a_lane_ending_on_the_axis_end_paints_on_the_track_edge(cx: &mut TestAppContext) {
    let (shell, cx) = boot_trajectory(
        cx,
        "traj-axis-end",
        &[(1, 1_000, Some(4_000)), (3, 5_000, Some(1_000))],
        true,
    );
    settle_lanes(cx, &shell);

    let track = cx.debug_bounds("traj-lane-tools").expect("the tools lane");
    let track_left = f32::from(track.origin.x);
    let track_w = f32::from(track.size.width);
    let track_right = track_left + track_w;
    // The event log is [user0, assistant1, tool2, user3, assistant4, tool5].
    let (left, right) = painted_span(cx, "traj-cell-hit-5");
    assert!(
        (right - track_right).abs() <= 1.0,
        "the last block's right edge is the track's right edge: {right} vs {track_right}"
    );
    assert!(
        right <= track_right + 1.0,
        "never past it: {right} vs {track_right}"
    );
    assert!(
        left >= track_left - 1.0,
        "and its left edge is still inside: {left} vs {track_left}"
    );
    assert!(
        ((right - left) - track_w * 0.2).abs() <= 2.0,
        "the real duration still sets the width: {} vs {}",
        right - left,
        track_w * 0.2
    );
}

/// A lane whose last event needs the 2px floor on the axis end stays fully
/// inside AND fully visible: the floor shifts the LEFT edge left by just enough
/// (the measured block is 2px wide with its right edge on the track's), rather
/// than growing 2px over the edge.
#[gpui::test]
fn the_pixel_floor_at_the_axis_end_stays_visible_and_inside(cx: &mut TestAppContext) {
    // The axis is 0..10s and the last call starts ON the axis end with a
    // zero duration: its x is exactly 1.0, so only the floor can make it
    // visible - and that floor is the width that used to paint past the track.
    let (shell, cx) = boot_trajectory(
        cx,
        "traj-floor-end",
        &[(1, 0, Some(10_000)), (3, 10_000, Some(0))],
        true,
    );
    settle_lanes(cx, &shell);

    let track = cx.debug_bounds("traj-lane-tools").expect("the tools lane");
    let track_left = f32::from(track.origin.x);
    let track_right = track_left + f32::from(track.size.width);
    let (left, right) = painted_span(cx, "traj-cell-hit-5");
    assert!(
        right - left >= 1.5,
        "the block is still visible at the very end: {}px wide",
        right - left
    );
    assert!(
        right <= track_right + 1.0,
        "and fully inside the track: {right} vs {track_right}"
    );
    assert!(
        (right - track_right).abs() <= 1.0,
        "the shifted block ends on the track's right edge, not before it: {right} vs {track_right}"
    );
    assert!(
        left >= track_left - 1.0,
        "without leaving the left edge: {left} vs {track_left}"
    );
}

/// EVERY block in EVERY lane obeys `left >= track_left` and
/// `right <= track_right`, and every block is also inside the strip's own
/// bounds.
///
/// The assertion sweeps the whole event log and derives each block's lane from
/// the event's kind, so one passing block cannot hide an overflowing neighbour.
/// It runs in both width readings: Duration keeps the real width and equal
/// width overrides it to 8px, which is the mode where a last block hung 8px
/// over the edge.
#[gpui::test]
fn every_lane_block_stays_inside_the_track_and_the_strip(cx: &mut TestAppContext) {
    let (shell, cx) = boot_trajectory(
        cx,
        "traj-all-blocks",
        &[
            (1, 1_000, Some(3_000)),
            (1, 5_000, Some(2_000)),
            (3, 8_000, Some(1_000)),
            // A zero-duration call ON the axis end: x = 1.0 in every reading.
            // Duration draws it at the 2px floor, equal width at 8px; both
            // used to hang past the track's right edge.
            (3, 10_000, Some(0)),
        ],
        true,
    );
    settle_lanes(cx, &shell);
    assert_blocks_inside(cx, &shell, "Duration");

    // The equal-width reading: still placed by the clock, drawn 8px wide.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.traj_actual_duration = false;
            cx.notify();
        })
    });
    settle_lanes(cx, &shell);
    let (left, right) = painted_span(cx, "traj-cell-hit-7");
    assert!(
        (right - left - 8.0).abs() <= 1.0,
        "the equal-width block is the measured 8px: {}",
        right - left
    );
    assert_blocks_inside(cx, &shell, "equal width");
}

/// At a 460px column the strip is short, and its right edge is close enough
/// that a block placed by fraction plus its floor is pressed against it. Every
/// block must still be inside its track and inside the strip's own bounds.
#[gpui::test]
fn the_strip_keeps_a_narrow_column_inside_its_own_bounds(cx: &mut TestAppContext) {
    let (shell, cx) = boot_trajectory(
        cx,
        "traj-narrow-strip",
        &[
            (1, 1_000, Some(3_000)),
            (1, 5_000, Some(2_000)),
            (3, 8_000, Some(1_000)),
            (3, 10_000, Some(0)),
        ],
        true,
    );
    settle_lanes(cx, &shell);
    resize_viewport(cx, 460.0);
    let narrow = shell.clone();
    draw_until(
        cx,
        "the narrow strip measures its own short track",
        DRAW_UNTIL_MAX,
        |cx| {
            let track = cx
                .debug_bounds("traj-lane-tools")
                .map(|bounds| f32::from(bounds.size.width));
            let measured = cx.update(|_, cx| narrow.read(cx).traj_lane_w.get());
            matches!((track, measured), (Some(track), Some(measured)) if (track - measured).abs() <= 1.5)
                && cx.debug_bounds("traj-cell-hit-7").is_some()
        },
    );
    // The frame that first saw the short width renders it; one draw applies it.
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let track = cx.debug_bounds("traj-lane-tools").expect("the tools lane");
    let track_w = f32::from(track.size.width);
    assert!(
        track_w > 100.0 && track_w < 460.0,
        "the harness really is on the short track, not the wide one: {track_w}"
    );
    assert_blocks_inside(cx, &shell, "460 column");
}

/// The chat's Inspect link opens the SAME call in the Trajectory tab: the tab
/// The chat's Inspect link opens the SAME call in the Trajectory tab: the tab
/// switches, the matching line is selected, and the detail panel shows it. Before
/// this the two tabs were unaware of each other, so a reader who wanted the whole
/// call had to unfold the transcript and then hunt for it in the log.
#[gpui::test]
fn the_inspect_link_opens_the_call_in_the_trajectory(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("inspect-link", 2);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "bash".to_string(),
                args: "{\"command\":\"ls\"}".to_string(),
                output: Some("a.txt".to_string()),
                ms: Some(7),
                at: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // The chip sits on a step of a settled turn, which the shipped 标准 policy
    // folds under the process group; opening the group is the reader's flow.
    let group = cx
        .debug_bounds("process-row-1")
        .expect("the settled steps fold under the process group");
    cx.simulate_click(group.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));

    // The chip is on the tool row of message 1, its only call.
    let chip = cx
        .debug_bounds("inspect-1-0")
        .expect("the inspect link renders");
    cx.simulate_click(chip.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let (tab, selected) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (shell.state.tab, shell.traj_select)
    });
    assert_eq!(tab, crate::state::Tab::Trajectory, "the tab switches");
    let selected = selected.expect("a line is selected");
    let events = cx.update(|_, cx| crate::ui::trajectory::events(shell.read(cx)));
    let event = &events[selected];
    assert_eq!(event.message, 1, "the selected line is that message");
    assert_eq!(event.tool, 0, "and that call");
    assert!(
        cx.debug_bounds("traj-detail").is_some(),
        "with its panel open"
    );
}
/// The turn's changed files render as the reference's closing card, and
/// hovering a row previews that file's comparison: the effect a reader asks
/// for when they want to see what an edit actually did.
#[gpui::test]
fn hovering_a_changed_file_previews_its_diff(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("changes-card", 1);
        tests_pin_reference_defaults(&mut state);
        let root = state.workspace_root().expect("a workspace root");
        // The file as it is NOW: the change has landed, which is what lets the
        // preview number its rows.
        std::fs::write(root.join("lib.rs"), "one\ntwo\nTHREE\nfour\n").expect("the file");
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "edit_file".to_string(),
                args: r#"{"path":"lib.rs","old_string":"three","new_string":"THREE"}"#.to_string(),
                output: Some("ok".to_string()),
                ms: Some(4),
                at: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // The card is on the assistant message that owns the write.
    draw_until(cx, "the changed-files card renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("changes-card-1").is_some()
    });
    assert!(
        cx.debug_bounds("changes-row-1-0").is_none(),
        "a single file is only a header, as the reference draws it"
    );
    assert!(
        cx.debug_bounds("changes-preview").is_none(),
        "nothing previews before the pointer arrives"
    );

    // Hover the header: the preview waits 500ms, then opens.
    let header = cx
        .debug_bounds("changes-header-1")
        .expect("the card header");
    cx.simulate_mouse_move(
        header.center(),
        None::<gpui_kit::MouseButton>,
        Modifiers::default(),
    );
    // The preview waits 500ms, and in a test that delay is the DETERMINISTIC
    // clock rather than wall time: a sleep advances nothing, so the timer would
    // never fire. Advancing the clock is what a 500ms delay means here.
    cx.background_executor
        .advance_clock(std::time::Duration::from_millis(600));
    cx.run_until_parked();
    draw_until(cx, "the preview opens", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("changes-preview").is_some()
    });
    // And it is a real comparison: the pane behind it is not needed, the card
    // names the file it explains.
    let hovered = cx.update(|_, cx| shell.read(cx).changes_preview.is_some());
    assert!(hovered, "the shell holds the preview it drew");
}

/// The Files tab carries the action that FEEDS the comparison pane. The Diff
/// tab on its own can never load anything, because a comparison needs a file
/// and that tab has no picker - which is why the surface read as unreachable.
#[gpui::test]
fn a_file_row_opens_the_comparison_pane(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_workspace_tree("right-diff-row");
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let toggle = cx
        .debug_bounds("hdr-show-right-panel")
        .expect("the header carries the right panel's toggle");
    cx.simulate_click(toggle.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let card = cx
        .debug_bounds("right-card-right.tab.files")
        .expect("the Files card renders");
    cx.simulate_click(card.center(), Modifiers::default());
    draw_until(cx, "the tree renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-README.md").is_some()
    });

    let action = cx
        .debug_bounds("diff-README.md")
        .expect("the README row carries its diff control");
    cx.simulate_click(action.center(), Modifiers::default());
    draw_until_settled(cx, "the comparison opens", |cx| {
        cx.update(|_, cx| shell.read(cx).right.diff.is_open())
    });

    let (tab, open) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (shell.right.tab, shell.right.open)
    });
    assert_eq!(
        tab,
        Some(crate::ui::right_panel::RightTab::Diff),
        "the panel switches to the comparison"
    );
    assert!(open, "and stays open");
    // A plain file with no patch opens as itself rather than as nothing, so
    // the pane answers "is this file dirty?" instead of going blank.
    assert!(cx.debug_bounds("diff-body").is_some(), "the file is drawn");
}

/// A step that wrote a file can open its change in the Diff pane: the chat
/// A step that wrote a file can open its change in the Diff pane: the chat
/// side's entry point. Without it the Diff tab could never load anything,
/// because a comparison needs a file and the tab has no file picker.
#[gpui::test]
fn a_write_step_opens_its_change_in_the_diff_pane(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("view-diff", 2);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "edit_file".to_string(),
                args:
                    r#"{"path":"src/lib.rs","old_string":"let a = 1;","new_string":"let a = 2;"}"#
                        .to_string(),
                output: Some("ok".to_string()),
                ms: Some(5),
                at: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // The premise: nothing is on the comparison surface yet.
    assert!(
        cx.update(|_, cx| !shell.read(cx).right.diff.is_open()),
        "the pane starts empty"
    );
    // The settled turn's steps live behind the process group under the shipped
    // 标准 policy; opening the group is the flow a reader performs.
    let group = cx
        .debug_bounds("process-row-1")
        .expect("the settled steps fold under the process group");
    cx.simulate_click(group.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let chip = cx
        .debug_bounds("view-diff-1-0")
        .expect("the step offers its diff");
    cx.simulate_click(chip.center(), Modifiers::default());
    draw_until(cx, "the comparison opens", DRAW_UNTIL_MAX, |cx| {
        cx.update(|_, cx| shell.read(cx).right.diff.is_open())
    });

    let (tab, open, conflicts) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (
            shell.right.tab,
            shell.right.open,
            shell.right.diff.conflicts,
        )
    });
    assert_eq!(
        tab,
        Some(crate::ui::right_panel::RightTab::Diff),
        "the panel switches to the comparison"
    );
    assert!(open, "and the panel is on screen");
    assert_eq!(conflicts, 0, "a patch carries no conflict to resolve");
    // The surface a reader lands on is usable, not an empty box.
    assert!(cx.debug_bounds("diff-body").is_some(), "the diff renders");
    assert!(
        cx.debug_bounds("diff-toolbar").is_some(),
        "with its mode and wrap controls"
    );
    assert!(
        cx.debug_bounds("diff-title").is_some(),
        "and a title naming the file"
    );
}

/// The Diff tab alone cannot load anything: a comparison needs a FILE. This is
/// the path the Files tab's action takes - a patch on disk opened as itself.
#[gpui::test]
fn a_patch_file_opens_as_a_comparison(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("diff-file", 1);
        tests_pin_reference_defaults(&mut state);
        let root = state.workspace_root().expect("a workspace root");
        std::fs::write(
            root.join("change.patch"),
            "--- a/lib.rs\n+++ b/lib.rs\n@@ -1,1 +1,1 @@\n-let a = 1;\n+let a = 2;\n",
        )
        .expect("the fixture");
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.open_diff(std::path::Path::new("change.patch"), cx);
        });
    });
    draw_until_settled(cx, "the patch opens", |cx| {
        cx.debug_bounds("diff-body").is_some()
    });
    let (tab, conflicts) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (shell.right.tab, shell.right.diff.conflicts)
    });
    assert_eq!(tab, Some(crate::ui::right_panel::RightTab::Diff));
    assert_eq!(conflicts, 0, "a patch has no conflict to resolve");
    assert!(
        cx.debug_bounds("diff-error").is_none(),
        "and it loaded without an error"
    );
}

/// The strip is a real tab list, not a badge for the pane already open: every
/// pane the Start screen offers is one press away, Diff included. This is the
/// entry point the pane never had - its body needs no file picker, so the only
/// door was the Start screen.
#[gpui::test]
fn the_right_strip_offers_the_diff_pane(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("strip-diff", 1);
        tests_pin_reference_defaults(&mut state);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    // The panel starts collapsed; open it and pick Files, so the strip is
    // showing one pane and must offer the others.
    let toggle = cx
        .debug_bounds("hdr-show-right-panel")
        .expect("the header carries the right panel's toggle");
    cx.simulate_click(toggle.center(), Modifiers::default());
    draw_until(cx, "the Start screen renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("right-card-right.tab.files").is_some()
    });
    let card = cx
        .debug_bounds("right-card-right.tab.files")
        .expect("the Files card renders");
    cx.simulate_click(card.center(), Modifiers::default());
    draw_until(cx, "the Files pane opens", DRAW_UNTIL_MAX, |cx| {
        cx.update(|_, cx| shell.read(cx).right.tab == Some(RightTab::Files))
    });

    // The strip offers Diff while Files holds the body.
    draw_until(cx, "the strip offers Diff", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("right-pane-diff").is_some()
    });
    let chip = cx
        .debug_bounds("right-pane-diff")
        .expect("the strip's Diff chip");
    cx.simulate_click(chip.center(), Modifiers::default());
    draw_until(cx, "the comparison pane opens", DRAW_UNTIL_MAX, |cx| {
        cx.update(|_, cx| shell.read(cx).right.tab == Some(RightTab::Diff))
    });
    assert!(
        cx.update(|_, cx| shell.read(cx).right.open),
        "the panel stays open on the pane the strip chose"
    );
    // Nothing is open yet, and the empty state says how a comparison arrives
    // rather than drawing a blank box.
    assert!(
        cx.debug_bounds("diff-pane").is_some(),
        "the Diff pane's body renders"
    );
    assert!(
        cx.debug_bounds("diff-empty-hint").is_some(),
        "with the hint that names its entry points"
    );
}

/// The turn-focused pane lists the files that turn wrote, expands a recorded
/// edit to its unified rows, and says plainly when a write recorded no old
/// text. The list comes from the tool requests, so no VCS and no invented
/// hunk is involved.
#[gpui::test]
fn a_turn_diff_lists_its_files_and_their_recorded_rows(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("turn-diff", 1);
        tests_pin_reference_defaults(&mut state);
        let root = state.workspace_root().expect("a workspace root");
        // The edit has landed, which is what lets the hunk be placed at its
        // real line rather than at a synthetic header.
        std::fs::write(root.join("lib.rs"), "fn main() {\n    let a = 2;\n}\n").expect("the file");
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].tools.push(ToolEvent {
                name: "edit_file".to_string(),
                args: r#"{"path":"lib.rs","old_string":"let a = 1;","new_string":"let a = 2;"}"#
                    .to_string(),
                output: Some("ok".to_string()),
                ms: Some(4),
                at: None,
            });
            session.messages[1].tools.push(ToolEvent {
                name: "write_file".to_string(),
                args: r##"{"path":"notes.md","content":"# Notes\nrewritten"}"##.to_string(),
                output: Some("ok".to_string()),
                ms: Some(3),
                at: None,
            });
            session.messages[1].tools.push(ToolEvent {
                name: "create_file".to_string(),
                args: r#"{"path":"new.rs","content":"fn new() {}"}"#.to_string(),
                output: Some("ok".to_string()),
                ms: Some(2),
                at: None,
            });
            // A command can change files the list will never name; the pane
            // says so rather than implying its list is the whole turn.
            session.messages[1].tools.push(ToolEvent {
                name: "bash".to_string(),
                args: r#"{"command":"touch side-effect.txt"}"#.to_string(),
                output: Some("ok".to_string()),
                ms: Some(1),
                at: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| this.open_diff_turn(1, cx));
    });
    draw_until(cx, "the turn list renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-file-0").is_some()
    });
    // The pane names the turn and lists all three files.
    let (tab, ordinal, message) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (
            shell.right.tab,
            shell.right.diff.turn.as_ref().map(|turn| turn.ordinal),
            shell.right.diff.turn.as_ref().map(|turn| turn.message),
        )
    });
    assert_eq!(tab, Some(RightTab::Diff), "the panel shows the comparison");
    assert_eq!(ordinal, Some(1), "the list names the turn it came from");
    assert_eq!(
        message,
        Some(1),
        "and it is the message the control named, not any other"
    );
    for index in 0..3 {
        let selector: &str = Box::leak(format!("diff-turn-file-{index}").into_boxed_str());
        assert!(
            cx.debug_bounds(selector).is_some(),
            "the list carries file {index}"
        );
    }
    assert!(
        cx.debug_bounds("diff-body").is_none(),
        "a turn list is not a kit file comparison"
    );
    assert!(
        cx.debug_bounds("diff-turn-command-note").is_some(),
        "a turn that also ran a command admits what the list cannot name"
    );

    // A recorded edit expands to a REAL before/after pair.
    let row = cx
        .debug_bounds("diff-turn-file-0")
        .expect("the first changed file");
    cx.simulate_click(row.center(), Modifiers::default());
    draw_until(cx, "the edit's rows open", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-line-0-0").is_some()
    });
    let rows = cx.update(|_, cx| {
        shell
            .read(cx)
            .right
            .diff
            .turn
            .as_ref()
            .and_then(|turn| turn.rows.get(&0))
            .cloned()
            .expect("the first file resolved its rows")
    });
    assert!(
        rows.iter()
            .any(|line| line.mark == '-' && line.text == "let a = 1;"),
        "the old side is the text the tool recorded: {rows:?}"
    );
    assert!(
        rows.iter()
            .any(|line| line.mark == '+' && line.text == "let a = 2;"),
        "the new side is what it asked for: {rows:?}"
    );

    // A write with no recorded old text says so, and draws no fake hunk.
    let row = cx
        .debug_bounds("diff-turn-file-1")
        .expect("the rewritten file");
    cx.simulate_click(row.center(), Modifiers::default());
    draw_until(cx, "the rewrite note opens", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-note-1").is_some()
    });
    assert!(
        cx.debug_bounds("diff-turn-line-1-0").is_none(),
        "a rewrite has no rows to draw"
    );
    let lang = cx.update(|_, cx| shell.read(cx).state.lang);
    let text = cx.update(|_, cx| {
        shell
            .read(cx)
            .right
            .diff
            .turn
            .as_ref()
            .and_then(|turn| turn.files.get(1))
            .map(|file| file.basis)
    });
    assert_eq!(
        text,
        Some(crate::ui::diff_pane::TurnBasis::Rewritten),
        "the basis is the recorded fact"
    );
    let note = crate::i18n::tr(lang, "diff.turnRewritten");
    assert_ne!(note, "diff.turnRewritten", "the note is a real string");
    assert!(
        note.contains("previous content") || note.contains("之前的内容"),
        "the note says the old side is unavailable: {note}"
    );

    // A creation is new, not a rewrite.
    let row = cx
        .debug_bounds("diff-turn-file-2")
        .expect("the created file");
    cx.simulate_click(row.center(), Modifiers::default());
    draw_until(cx, "the creation note opens", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-note-2").is_some()
    });
    let basis = cx.update(|_, cx| {
        shell
            .read(cx)
            .right
            .diff
            .turn
            .as_ref()
            .and_then(|turn| turn.files.get(2))
            .map(|file| file.basis)
    });
    assert_eq!(
        basis,
        Some(crate::ui::diff_pane::TurnBasis::NewFile),
        "a create records every line as new"
    );
    let note = crate::i18n::tr(lang, "diff.turnNewFile");
    assert!(
        note.to_lowercase().contains("new file") || note.contains("新文件"),
        "the note calls it a new file: {note}"
    );
}

/// The turn's own closing card is the control that opens the pane ON THAT
/// TURN. Two turns exist and only the second wrote anything; the pane must show
/// the second turn's files, and a row must open that one file inside the list.
#[gpui::test]
fn a_turn_card_opens_the_diff_pane_on_that_turn(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("turn-card", 2);
        tests_pin_reference_defaults(&mut state);
        let root = state.workspace_root().expect("a workspace root");
        std::fs::write(root.join("second.rs"), "let b = 2;").expect("the edited file");
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            // Only the SECOND turn (message 3) wrote; the first turn is clean.
            session.messages[3].tools.push(ToolEvent {
                name: "edit_file".to_string(),
                args: r#"{"path":"second.rs","old_string":"let b = 1;","new_string":"let b = 2;"}"#
                    .to_string(),
                output: Some("ok".to_string()),
                ms: Some(3),
                at: None,
            });
            session.messages[3].tools.push(ToolEvent {
                name: "write_file".to_string(),
                args: r#"{"path":"second.md","content":"rewritten"}"#.to_string(),
                output: Some("ok".to_string()),
                ms: Some(2),
                at: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    draw_until(cx, "the second turn's card renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("changes-card-3").is_some()
    });
    assert!(
        cx.debug_bounds("changes-card-1").is_none(),
        "the first turn wrote nothing, so it has no card"
    );

    // The header is the turn-level control.
    let header = cx
        .debug_bounds("changes-header-3")
        .expect("the closing card's header");
    cx.simulate_click(header.center(), Modifiers::default());
    draw_until(cx, "the turn list opens", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-file-0").is_some()
    });
    let (message, ordinal, files) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let turn = shell.right.diff.turn.as_ref();
        (
            turn.map(|turn| turn.message),
            turn.map(|turn| turn.ordinal),
            turn.map(|turn| {
                turn.files
                    .iter()
                    .map(|file| file.path.clone())
                    .collect::<Vec<_>>()
            }),
        )
    });
    assert_eq!(
        message,
        Some(3),
        "the pane targets the turn whose card was pressed"
    );
    assert_eq!(ordinal, Some(2), "which is the second turn");
    assert_eq!(
        files,
        Some(vec!["second.rs".to_string(), "second.md".to_string()]),
        "and lists only that turn's files"
    );
    assert!(
        cx.update(|_, cx| shell
            .read(cx)
            .right
            .diff
            .turn
            .as_ref()
            .is_some_and(|t| t.open.is_empty())),
        "a header press lists the files without opening one"
    );

    // A row opens the list on that file.
    let row = cx
        .debug_bounds("changes-row-3-1")
        .expect("the second file's row");
    cx.simulate_click(row.center(), Modifiers::default());
    draw_until(cx, "the row's file expands", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-note-1").is_some()
    });
    assert!(
        cx.update(|_, cx| shell
            .read(cx)
            .right
            .diff
            .turn
            .as_ref()
            .is_some_and(|turn| turn.open.contains(&1))),
        "the row's own file is the one expanded"
    );
}

/// An empty turn list names the turn and the reason it has nothing: a command
/// may change files without recording which ones, which is not the same fact
/// as a turn that changed nothing.
#[gpui::test]
fn an_empty_turn_diff_says_which_turn_and_why(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("turn-diff-empty", 2);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].tools.push(ToolEvent {
                name: "bash".to_string(),
                args: r#"{"command":"touch generated.txt"}"#.to_string(),
                output: Some("ok".to_string()),
                ms: Some(2),
                at: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // The command-only turn: its files are not individually captured.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| this.open_diff_turn(1, cx));
    });
    draw_until(cx, "the empty turn state renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-empty").is_some()
    });
    let empty = cx.update(|_, cx| {
        shell
            .read(cx)
            .right
            .diff
            .turn
            .as_ref()
            .and_then(|turn| turn.empty)
    });
    assert_eq!(
        empty,
        Some(crate::ui::diff_pane::TurnEmpty::CommandsOnly),
        "a shell command is 'not captured', not 'nothing changed'"
    );
    let lang = cx.update(|_, cx| shell.read(cx).state.lang);
    let text = crate::i18n::tr_args(lang, "diff.turnCommands", &[("turn", "1".to_string())]);
    assert!(
        text.contains('1') && !text.is_empty(),
        "the empty state names the turn: {text}"
    );
    assert_ne!(text, "diff.turnCommands", "and is a real string");

    // The turn that recorded nothing at all says exactly that.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| this.open_diff_turn(3, cx));
    });
    draw_until(cx, "the no-writes state renders", DRAW_UNTIL_MAX, |cx| {
        cx.debug_bounds("diff-turn-empty").is_some()
    });
    let empty = cx.update(|_, cx| {
        shell
            .read(cx)
            .right
            .diff
            .turn
            .as_ref()
            .and_then(|turn| turn.empty)
    });
    assert_eq!(
        empty,
        Some(crate::ui::diff_pane::TurnEmpty::NoWrites),
        "a turn with no writing tool changed no file"
    );
}

/// Every label the strip and the turn list draw is a real string in BOTH
/// locales: a missing key renders as itself, which is exactly the raw
/// `right.tab.diff` the screenshot showed.
#[test]
fn the_diff_labels_are_real_in_both_locales() {
    let keys = [
        "right.tab.files",
        "right.tab.terminal",
        "right.tab.browser",
        "right.tab.diff",
        "right.diff.hint",
        "right.notBuilt",
        "diff.empty",
        "diff.emptyHint",
        "diff.turnTitle",
        "diff.turnEmpty",
        "diff.turnCommands",
        "diff.turnCommandNote",
        "diff.turnNewFile",
        "diff.turnRewritten",
        "diff.turnMore",
    ];
    for key in keys {
        for lang in [Lang::En, Lang::Zh] {
            let text = crate::i18n::tr(lang, key);
            assert!(!text.is_empty(), "\"{key}\" has no value in one locale");
            assert_ne!(text, key, "\"{key}\" rendered as its raw key in one locale");
        }
    }
    // The exact wording of the two honest notes, so a rename cannot slip past
    // the pane test above.
    assert_eq!(
        crate::i18n::tr(Lang::En, "diff.turnNewFile"),
        "New file — no previous content was recorded"
    );
    assert_eq!(
        crate::i18n::tr(Lang::En, "diff.turnRewritten"),
        "Rewritten — previous content unavailable"
    );
    assert_eq!(
        crate::i18n::tr(Lang::Zh, "diff.turnNewFile"),
        "新文件 — 未记录之前的内容"
    );
}

/// The changed-files scaffolding was parked under a `dead_code` allow "wired
/// by the changed-files panel that is landing next". It has landed, so the
/// allow must be gone: clippy proves the symbols are used, and this pins the
/// comment so a parking note cannot creep back.
#[test]
fn the_changed_files_scaffolding_is_not_parked_under_dead_code() {
    let transcript = include_str!("transcript.rs");
    assert!(
        !transcript.contains("wired by the changed-files panel"),
        "transcript.rs still parks the changed-files scaffolding"
    );
    let theme = include_str!("../theme.rs");
    assert!(
        !theme.contains("wired by the changed-files panel"),
        "theme.rs still parks the changed-files scaffolding"
    );
}

/// A call that started while another was still running is a SUBTOOL, indented
/// A call that started while another was still running is a SUBTOOL, indented
/// under it. The nesting is derived from the recorded times, so it needs no
/// parent column and works on logs already on disk.
#[gpui::test]
fn a_call_inside_another_becomes_a_subtool(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("subtool", 1);
        tests_pin_reference_defaults(&mut state);
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            let tool = |name: &str, at: u64, ms: u64| crate::model::ToolEvent {
                name: name.to_string(),
                args: "{}".to_string(),
                output: Some("ok".to_string()),
                ms: Some(ms),
                at: Some(at),
            };
            // The outer call runs 1_000..6_000; the inner starts at 2_000.
            session.messages[1]
                .tools
                .push(tool("run_code", 1_000, 5_000));
            session.messages[1]
                .tools
                .push(tool("job_output", 2_000, 100));
            session.messages[1].tools.push(tool("bash", 7_000, 100));
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let kinds = cx.update(|_, cx| {
        crate::ui::trajectory::events(shell.read(cx))
            .into_iter()
            .filter(|e| e.tool != usize::MAX)
            .map(|e| e.kind)
            .collect::<Vec<_>>()
    });
    use crate::ui::trajectory::Kind;
    assert_eq!(
        kinds,
        vec![Kind::Tool, Kind::Subtool, Kind::Tool],
        "the call inside the running one is the only subtool"
    );

    // And it draws one rail in from its parent.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.state.tab = Tab::Trajectory;
            cx.notify();
        });
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    // The tool rows are not the first three events (the turn's messages come
    // first), so read the indices the log actually gives them.
    let tool_rows: Vec<usize> = cx.update(|_, cx| {
        crate::ui::trajectory::events(shell.read(cx))
            .iter()
            .enumerate()
            .filter(|(_, e)| e.tool != usize::MAX)
            .map(|(index, _)| index)
            .collect()
    });
    let rows: Vec<f32> = tool_rows
        .iter()
        .filter_map(|index| {
            let selector: &str = Box::leak(format!("traj-row-{index}").into_boxed_str());
            cx.debug_bounds(selector).map(|b| f32::from(b.origin.x))
        })
        .collect();
    assert!(rows.len() == 3, "the three calls render: {rows:?}");
    assert!(
        rows[1] > rows[0] + 10.0,
        "the subtool sits indented: {rows:?}"
    );
}
/// A file step's path is a link: pressing it opens the file in the right
/// panel's editor, which is where the reference puts it.
#[gpui::test]
fn a_file_step_opens_in_the_right_panel_editor(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("open-file", 1);
        tests_pin_reference_defaults(&mut state);
        let root = state.workspace_root().expect("a workspace root");
        // A path LONGER than the row's 96-char display clip, because the summary
        // is clipped for display and opening it must not use the clipped text -
        // that was the bug: a long path resolved to one that does not exist.
        let deep = "crates/bsh/src/ui/very/deeply/nested/directory/whose/name/is/long/module_with_an_extremely_long_name_for_testing.rs";
        std::fs::create_dir_all(root.join(deep).parent().expect("a parent")).expect("a directory");
        std::fs::write(root.join(deep), "fn main() {}\n").expect("a file");
        let id = state.active_id.clone().expect("an active session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[1].tools.push(crate::model::ToolEvent {
                name: "read_file".to_string(),
                // An ABSOLUTE path, which is what a tool is usually handed and
                // what the panel's resolver used to refuse with "leaves the
                // workspace" even though the file is inside it.
                args: format!(
                    "{{\"path\":\"{}/crates/bsh/src/ui/very/deeply/nested/directory/whose/name/is/long/module_with_an_extremely_long_name_for_testing.rs\"}}",
                    root.display()
                ),
                output: Some("fn main() {}".to_string()),
                ms: Some(3),
                at: None,
            });
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    // The settled turn's steps live behind the process group; open it first.
    let group = cx
        .debug_bounds("process-row-1")
        .expect("the settled steps fold under the process group");
    cx.simulate_click(group.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let link = cx
        .debug_bounds("open-file-1-0")
        .expect("the path renders as a link");
    cx.simulate_click(link.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));

    // Discrimination: the row's summary IS clipped (over 96 chars) while the
    // path the link opens is not, so a link that used the summary would resolve
    // a path that does not exist.
    let summary = crate::ui::transcript::tool_summary(&format!(
        "{{\"path\":\"{}\"}}",
        "crates/bsh/src/ui/very/deeply/nested/directory/whose/name/is/long/module_with_an_extremely_long_name_for_testing.rs"
    ));
    assert!(
        summary.ends_with('\u{2026}'),
        "the displayed summary is clipped: {summary}"
    );

    let (open, tab, files, error) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        (
            shell.right.open,
            shell.right.tab,
            shell.files.tabs.len(),
            shell.files.error.clone(),
        )
    });
    assert_eq!(error, None, "the exact path resolves: {error:?}");
    assert!(open, "the panel is revealed");
    // The row must NOT have folded: the live click unfolded it instead of opening
    // the file, because the fold handler sat on the whole row.
    let folded = cx.update(|_, cx| shell.read(cx).state.tool_open(1, 0));
    assert!(
        !folded,
        "the press opened the file, it did not fold the step"
    );
    assert_eq!(
        tab,
        Some(crate::ui::right_panel::RightTab::Files),
        "on the files pane"
    );
    assert_eq!(files, 1, "with the file opened as a tab");
}
