/// Adding a folder registers it as a workspace and switches to it.
///
/// This is the half of the flow the picker feeds: a directory goes in once (a
/// second add of the same root selects it), becomes active, and the file pane
/// rebases onto its tree.
#[gpui::test]
fn a_folder_can_be_added_as_a_workspace(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("workspace-add", 1);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../target")
        .join(format!(
            "bsh-scratch-added-workspace-{}",
            std::process::id()
        ));
    let _ = std::fs::remove_dir_all(&root);
    let _ = std::fs::create_dir_all(&root);
    let _ = std::fs::write(root.join("added.txt"), b"hello\n");
    let root_text = root.to_string_lossy().to_string();

    // The file pane only re-lists while it is the pane on screen, which is the
    // behaviour that keeps a closed panel from walking the filesystem.
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| {
            this.open_right_tab(crate::ui::right_panel::RightTab::Files, cx);
        });
    });
    cx.update(|_, cx| {
        shell.update(cx, |this, cx| this.adopt_workspace(&root, cx));
    });

    // The Add workspace path also drops the inert authoring templates into the
    // folder, and only those: the enforcing files stay absent.
    for name in [
        crate::workspace_templates::POLICY_TEMPLATE_NAME,
        crate::workspace_templates::ALLOWLIST_TEMPLATE_NAME,
        crate::workspace_templates::TERMINAL_TEMPLATE_NAME,
    ] {
        assert!(
            root.join(".bsh").join(name).is_file(),
            "{name} is missing after the add"
        );
    }
    assert!(!root.join(".bsh").join("policy.rego").exists());
    assert!(!root.join(".bsh").join("egress-allowlist").exists());
    assert!(!root.join(".bsh").join("terminal-policy.rego").exists());

    let (active, registered, listed) = cx.update(|_, cx| {
        let shell = shell.read(cx);
        let settings = &shell.state.settings;
        let active = settings.global.general.active_workspace.clone();
        let registered = settings
            .global
            .workspaces
            .iter()
            .any(|workspace| workspace.root == root_text);
        let listed = shell.files.roots.iter().any(|row| row.name == "added.txt");
        (active, registered, listed)
    });
    assert!(registered, "the folder is registered as a workspace");
    assert!(
        !active.is_empty(),
        "and one workspace is in use after the add"
    );
    assert!(
        listed,
        "the file pane re-listed onto the new tree: {:?}",
        cx.update(|_, cx| {
            shell
                .read(cx)
                .files
                .roots
                .iter()
                .map(|row| row.name.clone())
                .collect::<Vec<_>>()
        })
    );
    let _ = std::fs::remove_dir_all(&root);
}
/// The session menu carries the reference's five actions.
///
/// It drew two (Pin, Archive) while the reference offers rename, fork and copy
/// as well - operations a reader reaches for at exactly the moment they open
/// this menu.
#[gpui::test]
fn the_session_menu_carries_the_reference_five_actions(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (_harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("session-menu", 2);
        // A fixed id, because `debug_bounds` wants a literal selector.
        let id = state.active_id.clone().expect("a session");
        if let Some(session) = state.store.session_mut(&id) {
            session.id = String::from("menu-target");
        }
        state.active_id = Some(String::from("menu-target"));
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));

    let more = cx
        .debug_bounds("more-menu-target")
        .expect("the row carries its menu control");
    cx.simulate_click(more.center(), Modifiers::default());
    cx.update(|window, cx| window.draw(cx).clear(cx));

    for (selector, what) in [
        ("session-menu-pin", "pin"),
        ("session-menu-rename", "rename"),
        ("session-menu-fork", "fork"),
        ("session-menu-archive", "archive"),
        ("session-menu-copy", "copy the id"),
    ] {
        assert!(
            cx.debug_bounds(selector).is_some(),
            "the menu offers {what}: {selector}"
        );
    }
}

/// Rename retitles the session in place, from a field on its own row.
#[gpui::test]
fn rename_retitles_the_session_from_its_own_row(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("session-rename", 2);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    let id = cx.update(|_, cx| shell.read(cx).state.active_id.clone().expect("a session"));

    cx.update(|window, cx| {
        shell.update(cx, |this, cx| this.begin_session_rename(&id, window, cx));
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert!(
        cx.debug_bounds("session-rename").is_some(),
        "the field appears on the row being renamed"
    );

    cx.update(|window, cx| {
        shell.update(cx, |this, cx| {
            this.session_rename.update(cx, |state, cx| {
                state.set_value(String::from("Renamed by hand"), window, cx);
            });
            this.commit_session_rename(cx);
        });
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    assert_eq!(
        cx.update(|_, cx| shell.read(cx).state.session_title(&id)),
        Some(String::from("Renamed by hand")),
        "the title the reader typed is the one stored"
    );
    assert!(
        cx.debug_bounds("session-rename").is_none(),
        "and the field goes away"
    );
}

/// Fork branches a session: a new id carrying the same transcript.
#[gpui::test]
fn fork_copies_the_transcript_into_a_new_session(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let state = state_with_turns("session-fork", 3);
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    let original = cx.update(|_, cx| shell.read(cx).state.active_id.clone().expect("a session"));

    cx.update(|_, cx| {
        shell.update(cx, |this, cx| this.fork_session_at(&original, cx));
    });

    let (forked, original_messages, forked_messages) = cx.update(|_, cx| {
        let state = &shell.read(cx).state;
        let forked = state.active_id.clone().expect("the fork opens");
        let original_messages = state
            .store
            .session(&original)
            .expect("the original")
            .messages
            .len();
        let forked_messages = state
            .store
            .session(&forked)
            .expect("the fork")
            .messages
            .len();
        (forked, original_messages, forked_messages)
    });
    assert_ne!(forked, original, "the fork is its own session");
    assert_eq!(
        forked_messages, original_messages,
        "and it carries the transcript it branched from"
    );
}

/// An unchanged frame must reuse the parsed markdown body, not re-parse it.
///
/// The kit decides whether to reparse by comparing the ALLOCATION it is handed;
/// handing it a fresh clone every frame made every visible row re-parse its
/// whole body per frame. The shell holds one state per body instead.
#[gpui::test]
fn a_redraw_does_not_reparse_the_markdown_bodies(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (_harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("body-cache", 6);
        let id = state.active_id.clone().expect("a session");
        let body = "## 五\n\n列车进站，车门打开。车厢里坐着一个女孩。\n".repeat(40);
        if let Some(session) = state.store.session_mut(&id) {
            for message in session.messages.iter_mut() {
                if message.role == crate::model::Role::Assistant {
                    message.text = body.clone();
                }
            }
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    // The first frames parse what they paint and fill the cache.
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let parsed = crate::ui::shell::bodies_parsed();
    assert!(parsed > 0, "the first frames parse the visible bodies");
    for _ in 0..3 {
        cx.update(|window, cx| window.draw(cx).clear(cx));
    }
    assert_eq!(
        crate::ui::shell::bodies_parsed(),
        parsed,
        "an unchanged frame re-parsed a body instead of reusing its state"
    );
}
/// A branch opens a conversation that renders the rows the reader is already
/// looking at, so the first frame after the click must be a PAINT: no full
/// re-measure, and only the rows near the viewport built.
///
/// Measured before this: a 30-turn branch took 1.36s because the new session
/// was a layout cache miss and every row was rebuilt.
#[gpui::test]
fn a_branch_adopts_the_layout_it_was_cut_from(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("branch-layout", 30);
        let id = state.active_id.clone().expect("a session");
        let body = "## 五\n\n列车进站，车门打开。车厢里坐着一个女孩。\n".repeat(60);
        if let Some(session) = state.store.session_mut(&id) {
            for message in session.messages.iter_mut() {
                if message.role == crate::model::Role::Assistant {
                    message.text = body.clone();
                    message.timing_mut().start = Some(crate::state::now_ms());
                    message.timing_mut().ms = Some(1_200);
                }
            }
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());
    let resets_before = crate::ui::transcript::transcript_layout_resets();
    let built_before = crate::ui::transcript::transcript_rows_built();

    let last: &str = Box::leak(String::from("branch-59").into_boxed_str());
    let bounds = cx
        .debug_bounds(last)
        .expect("the newest reply's branch control");
    cx.simulate_click(bounds.center(), Modifiers::default());
    draw_until(cx, "the branch opens", DRAW_UNTIL_MAX, |_cx| {
        shell.read_with(_cx, |this, _| {
            this.state
                .active_session()
                .map(|session| session.title.contains("(2)"))
                .unwrap_or(false)
        })
    });

    assert_eq!(
        crate::ui::transcript::transcript_layout_resets(),
        resets_before,
        "a branch re-measured the whole transcript instead of adopting its rows"
    );
    let built = crate::ui::transcript::transcript_rows_built() - built_before;
    assert!(
        built < 45,
        "the first frame after a branch built {built} of 60 rows; it must build the viewport"
    );
}
/// A prompt carries its own footer: the time it was sent, then copy - right
/// under the bubble and aligned to its right edge.
#[gpui::test]
fn a_prompt_carries_its_time_and_a_copy_control(cx: &mut TestAppContext) {
    init_test_app(cx);
    let (harness, cx) = cx.add_window_view(move |window, cx| {
        let mut state = state_with_turns("user-actions", 1);
        let id = state.active_id.clone().expect("a session");
        if let Some(session) = state.store.session_mut(&id) {
            session.messages[0].text = "aa".to_string();
            session.messages[0].timing_mut().start = Some(crate::state::now_ms());
            session.messages[1].timing_mut().start = Some(crate::state::now_ms());
        }
        let shell = cx.new(|cx| Shell::build_for_test(window, None, state, cx));
        Harness { shell }
    });
    cx.update(|window, cx| window.draw(cx).clear(cx));
    cx.update(|window, cx| window.draw(cx).clear(cx));
    let shell = cx.update(|_, cx| harness.read(cx).shell.clone());

    let bubble = cx
        .debug_bounds("user-bubble-0")
        .expect("the bubble renders");
    let actions = cx
        .debug_bounds("user-actions-0")
        .expect("the prompt's action row renders");
    let copy = cx
        .debug_bounds("user-copy-0")
        .expect("its copy control renders");
    assert!(
        actions.origin.y >= bubble.origin.y + bubble.size.height,
        "the row sits below the bubble, not beside it"
    );
    assert_eq!(
        actions.origin.x + actions.size.width,
        bubble.origin.x + bubble.size.width,
        "and it ends at the bubble's right edge"
    );
    assert_eq!(copy.size.width, px(28.0), "a measured 28px square");

    cx.simulate_click(copy.center(), Modifiers::default());
    draw_until(cx, "the prompt records the copy", DRAW_UNTIL_MAX, |_cx| {
        shell.read_with(_cx, |this, _| this.copied_message == Some(0))
    });
    assert_eq!(
        cx.read_from_clipboard().and_then(|item| item.text()),
        Some("aa".to_string()),
        "the copy control writes the prompt, not the reply"
    );
}
